// ── source: vcx/tests/store_serve_tls_test.v ──
// store_serve_tls_test.v — #180: `cx store-serve` with a [tls cert= key=] config
// must actually bind a TLS listener (the cert/key were parsed then discarded, so
// any [tls] config exited(1) with E_NET_TLS_CONFIG). End-to-end: generate a
// self-signed cert, start the daemon with TLS, and assert it binds (no exit(1),
// prints "listening") and answers an HTTPS capabilities probe. Also exercises
// #199 (${env:VAR} key injection). Skips cleanly without openssl/curl.

fn tls_cx_binary() string {
	return testenv.cx_bin()
}

fn tls_pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26720 + int(salt)
}

fn test_store_serve_tls_bind() {
	if os.execute('command -v openssl').exit_code != 0 {
		eprintln('SKIP: openssl not available for TLS bind test')
		return
	}
	if os.execute('command -v curl').exit_code != 0 {
		eprintln('SKIP: curl not available for TLS bind test')
		return
	}
	port := tls_pick_port()
	dir := os.join_path(os.temp_dir(), 'cx_tls_${port}')
	os.mkdir_all(dir) or { panic('mkdir ${dir}: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	cert := os.join_path(dir, 'tls.crt')
	key := os.join_path(dir, 'tls.key')
	gen := os.execute('openssl req -x509 -newkey rsa:2048 -keyout ${key} -out ${cert} -days 1 -nodes -subj "/CN=127.0.0.1" 2>/dev/null')
	if gen.exit_code != 0 {
		eprintln('SKIP: openssl cert generation failed')
		return
	}
	// #199: inject the key path via ${env:VAR} to also cover env resolution.
	os.setenv('CX_TLS_KEY_PATH', key, true)
	cfg_path := os.join_path(dir, 'svc.cx')
	cfg := '[cxstore-service [bind addr="127.0.0.1:${port}"] [tls cert="${cert}" key="\${env:CX_TLS_KEY_PATH}"] [stores [store name="teststore" url="mem://"]]]'
	os.write_file(cfg_path, cfg) or { panic('write cfg: ${err}') }

	srv_out := os.join_path(dir, 'srv.out')
	// the store-serve subcommand comes FIRST; it parses its own --allow-* flags.
	allow := '--allow-net=127.0.0.1:${port} --allow-read=${dir}'
	pid_s := os.execute('${tls_cx_binary()} store-serve ${allow} --config ${cfg_path} >${srv_out} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx store-serve')
		return
	}
	pid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
	}
	time.sleep(800 * time.millisecond) // let it bind

	srv_log := os.read_file(srv_out) or { '' }
	// the #180 bug: any [tls] config → exit(1) with E_NET_TLS_CONFIG at bind.
	assert !srv_log.contains('E_NET_TLS_CONFIG'), 'TLS bind must not fail with E_NET_TLS_CONFIG (#180); server log: ${srv_log}'
	assert !srv_log.contains('CXER4514'), 'TLS bind must not fail (#180); server log: ${srv_log}'
	assert srv_log.contains('listening on tls://'), 'daemon must report a TLS listener; server log: ${srv_log}'

	// HTTPS capabilities probe (self-signed → -k) must succeed over the TLS wire.
	probe := os.execute('curl -sk --max-time 3 https://127.0.0.1:${port}/cx-store/v1/capabilities')
	assert probe.exit_code == 0, 'HTTPS capabilities probe failed (exit ${probe.exit_code}); server log: ${srv_log}'
	assert probe.output.contains('capabilities'), 'HTTPS probe did not return a capabilities body; got: ${probe.output} | server log: ${srv_log}'
}

// ── source: vcx/tests/store_tls_rotation_test.v ──
// store_tls_rotation_test.v — #251 (§2.6 / CSRP §3.13): TLS certificate
// rotation WITHOUT a restart. End-to-end over the real wire: start
// `cx store-serve` with cert A, read the served certificate's fingerprint via
// `openssl s_client`, overwrite the cert/key FILES with a fresh identity B
// (the config document itself is untouched — this is exactly the file-based
// rotation path the spec mandates, caught by content-compare, not section
// diff), trigger the admin `config-reload` op over HTTPS, and assert a NEW
// handshake presents B's fingerprint. The live consumer of the mbedtls
// SSLListener.rotate_certs fork seam. Skips cleanly without openssl/curl.

fn rot_cx_binary() string {
	return testenv.cx_bin()
}

fn rot_pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26920 + int(salt)
}

fn rot_fingerprint(port int) string {
	r := os.execute('echo | openssl s_client -connect 127.0.0.1:${port} 2>/dev/null | openssl x509 -noout -fingerprint -sha256 2>/dev/null')
	if r.exit_code != 0 {
		return ''
	}
	return r.output.trim_space()
}

fn test_store_serve_tls_cert_rotation() {
	if os.execute('command -v openssl').exit_code != 0 {
		eprintln('SKIP: openssl not available for TLS rotation test')
		return
	}
	if os.execute('command -v curl').exit_code != 0 {
		eprintln('SKIP: curl not available for TLS rotation test')
		return
	}
	port := rot_pick_port()
	dir := os.join_path(os.temp_dir(), 'cx_tlsrot_${port}')
	os.mkdir_all(dir) or { panic('mkdir ${dir}: ${err}') }
	defer {
		os.rmdir_all(dir) or {}
	}
	cert := os.join_path(dir, 'tls.crt')
	key := os.join_path(dir, 'tls.key')
	gen_a := os.execute('openssl req -x509 -newkey rsa:2048 -keyout ${key} -out ${cert} -days 1 -nodes -subj "/CN=127.0.0.1" 2>/dev/null')
	if gen_a.exit_code != 0 {
		eprintln('SKIP: openssl cert generation failed')
		return
	}
	admin_hash := sha256.sum256('rot-admin-secret'.bytes()).hex()
	cfg_path := os.join_path(dir, 'svc.cx')
	cfg := '[cxstore-service [bind addr="127.0.0.1:${port}"] [tls cert="${cert}" key="${key}"] [stores [store name="teststore" url="mem://"]] [auth [static [token id="root" secret-hash="sha256:${admin_hash}" roles="admin" tenant="*"]]]]'
	os.write_file(cfg_path, cfg) or { panic('write cfg: ${err}') }

	srv_out := os.join_path(dir, 'srv.out')
	allow := '--allow-net=127.0.0.1:${port} --allow-read=${dir}'
	pid_s := os.execute('${rot_cx_binary()} store-serve ${allow} --config ${cfg_path} >${srv_out} 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx store-serve')
		return
	}
	pid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
	}
	// wait for the TLS listener
	mut up := false
	for _ in 0 .. 50 {
		probe := os.execute('curl -sk --max-time 2 https://127.0.0.1:${port}/cx-store/v1/ready')
		if probe.exit_code == 0 && probe.output.contains('[accepting true]') {
			up = true
			break
		}
		time.sleep(100 * time.millisecond)
	}
	if !up {
		srv_log := os.read_file(srv_out) or { '' }
		eprintln('SKIP: TLS daemon did not become ready; server log: ${srv_log}')
		return
	}

	fp_a := rot_fingerprint(port)
	assert fp_a != '', 'must read the served certificate fingerprint (identity A)'

	// Rotate the identity ON DISK — same paths, fresh key+cert. The config
	// document is byte-identical; only the PEM content-compare can catch this.
	gen_b := os.execute('openssl req -x509 -newkey rsa:2048 -keyout ${key} -out ${cert} -days 1 -nodes -subj "/CN=127.0.0.1" 2>/dev/null')
	assert gen_b.exit_code == 0, 'openssl re-generation must succeed'

	rl := os.execute('curl -sk --max-time 3 -X POST -H "Authorization: Bearer rot-admin-secret" https://127.0.0.1:${port}/cx-store/v1/config-reload')
	assert rl.exit_code == 0, 'config-reload over HTTPS must succeed (exit ${rl.exit_code})'
	assert rl.output.contains('applied=true'), 'rotation reload must apply: ${rl.output}'
	assert rl.output.contains('tls'), 'changed list must name tls: ${rl.output}'

	fp_b := rot_fingerprint(port)
	assert fp_b != '', 'must read the served certificate fingerprint (identity B)'
	assert fp_b != fp_a, 'a NEW handshake after rotation must present the rotated certificate (A=${fp_a})'

	// and the daemon still serves over the rotated identity
	post := os.execute('curl -sk --max-time 3 https://127.0.0.1:${port}/cx-store/v1/ready')
	assert post.exit_code == 0 && post.output.contains('[accepting true]'), 'daemon must keep serving after rotation'
}

// ── source: vcx/tests/store_xsp_client_test.v ──
// store_xsp_client_test.v — BEHAVIORAL proof of the XSP STORE-PROFILE CLIENT
// (I5 stream 4 W6; spec/03-approved/xap/xsp_store_profile.md §8 migration order:
// "remote client via ObjWireTransport"). The REAL `cx store-serve` daemon
// boots with the [xsp] listener enabled (floor policy), and a cx program
// drives the FULL Layer-1 porcelain over `cx-store+xsp://` — the store URL
// scheme whose transport is the profile (bare `cx-store://` = the same
// profile over TLS; store.md §2 wire row). Everything below crosses the wire
// through the third ObjWireTransport impl + the profile client arms:
//
//   put-doc → get-doc                     → hash BYTE-IDENTICAL to the local
//                                           embedded put of the same doc (M5);
//                                           put rides the OBJECT wire (have →
//                                           put-missing → refs-set), get
//                                           resolves the ref + reconstructs
//   exists / list-docs / delete-doc       → the daemon's authoritative catalog
//   query pushdown                        → server-side CXPath, never a silent
//                                           empty local scan (#119 posture)
//   iter-docs                             → server-side iter events + eos
//   set-alias / get-alias / list-aliases  → the daemon's authoritative alias
//                                           table (#645), explicit absence
//   modify-doc                            → server-side modify, new hash back
//   status / gc                           → the porcelain elements verbatim
//   error identity                        → CXER1121 verbatim for get-doc-text
//                                           of an absent hash (profile error
//                                           transparency — never a remap)
//   mounts (anonymous, open posture)      → refused: daemon-level admin needs
//                                           a DID-proven principal (CXER5018)
//   mounts (xsp-did/xsp-seed-env opts)    → mutual attach; the mount table
//
// Black-box like store_csrp_test.v: no Docker, loopback net only.

const xc_host_did = 'did:key:z6MkiaMbhXHNA4eJVCCj8dbzKzTgYDKf6crKgHVHid1F1WCT' // RFC 8032 TEST 2

const xc_host_seed_hex = '4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb'

const xc_client_did = 'did:key:z6MktwupdmLXVVqTzCw4i46r4uGyosGXRnR3XjN4Zq7oMMsw' // RFC 8032 TEST 1

const xc_client_seed_hex = '9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60'

// Disjoint port band (27460-27499) from the serve test (27350) / fabric
// (27100) / http (26400) / csrp (26600).
fn xc_pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 20
	return 27460 + int(salt) * 2
}

fn xc_write(dir string, name string, content string) string {
	p := os.join_path(dir, name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

// xc_boot boots one `cx store-serve` daemon with the [xsp] listener on
// port+1 (floor policy — anonymous clients admitted as "guest").
fn xc_boot() (int, int, string, &os.Process) {
	cxbin := testenv.cx_bin()
	port := xc_pick_port()
	xport := port + 1
	tmp := os.join_path(os.temp_dir(), 'cx-store-xsp-client-test-${os.getpid()}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic('mkdir ${tmp}: ${err}') }
	cfg := '[cxstore-service
  [bind addr="127.0.0.1:${port}"]
  [stores [store name="main" url="file://${tmp}/store"]]
  [xsp enabled=true addr="127.0.0.1:${xport}"
    [identity did="${xc_host_did}" seed-env="CX_STORE_XSP_CLIENT_TEST_SEED"]
    [policy mode=floor floor="guest"]]
  [workers query-pool=2]]'
	cfg_path := xc_write(tmp, 'cxstore.service.cx', cfg)
	os.setenv('CX_STORE_XSP_CLIENT_TEST_SEED', xc_host_seed_hex, true)
	mut proc := os.new_process('/bin/sh')
	proc.set_args(['-c',
		'exec "${cxbin}" store-serve --config "${cfg_path}" --exit-on-stdin-eof --allow-read --allow-write --allow-net=127.0.0.1:${port} --allow-net=127.0.0.1:${xport} --allow-env >"${tmp}/daemon.log" 2>&1'])
	proc.set_redirect_stdio()
	proc.run()
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := http.get('http://127.0.0.1:${port}/cx-store/v1/ready') or { continue }
		if r.status_code == 200 && r.body.contains('[accepting true]') {
			up = true
			break
		}
	}
	if !up {
		proc.signal_kill()
		out := os.read_file(os.join_path(tmp, 'daemon.log')) or { '' }
		panic('store-serve never came up: ${out}')
	}
	return port, xport, tmp, proc
}

fn xc_stop(mut proc os.Process, tmp string) {
	proc.signal_kill()
	proc.wait()
	os.rmdir_all(tmp) or {}
}

// xc_run runs one client cx program against the daemon; loopback net only.
fn xc_run(tmp string, xport int, name string, prog string) os.Result {
	p := xc_write(tmp, name, prog)
	return os.execute('${testenv.cx_bin()} --allow-net=127.0.0.1:${xport} --allow-env ${p}')
}

const xc_lib = "[?lib 'cx-stdlib/store' :as store]\n"

fn test_xsp_client_full_surface() {
	port, xport, tmp, mut proc := xc_boot()
	defer {
		xc_stop(mut proc, tmp)
	}
	url := 'cx-store+xsp://127.0.0.1:${xport}/main/'

	// ── bootstrap discovery (profile spec §8): the server-level capabilities
	// advert names THE store wire — the [xsp] listener address + responder
	// DID — so a management client finds the profile from the HTTP base ──────
	caps := http.get('http://127.0.0.1:${port}/cx-store/v1/capabilities') or {
		panic('capabilities fetch: ${err}')
	}
	assert caps.status_code == 200, 'capabilities status ${caps.status_code}'
	assert caps.body.contains('[xsp [addr "127.0.0.1:${xport}"]'), 'capabilities must advertise the [xsp] listener addr: ${caps.body}'
	assert caps.body.contains(xc_host_did), 'capabilities must advertise the responder DID: ${caps.body}'

	// ── put → get round trip; the M5 byte-identical-address oracle ──────────
	rt := xc_run(tmp, xport, 'rt.cx', xc_lib +
		'[?let [= \$local [\$store:open "mem://xc-oracle"]]\n' +
		'[?let [= \$hl [\$store:put-doc \$local [note [title "xsp-client"] [body "w6-round-trip"]]]]\n' +
		'[?let [= \$c [\$store:open "${url}"]]\n' +
		'[?let [= \$h [\$store:put-doc \$c [note [title "xsp-client"] [body "w6-round-trip"]]]]\n' +
		'[?let [= \$got [\$store:get-doc-text \$c \$h]]\n' +
		'[?let [= \$before [\$store:exists \$c \$h]]\n' +
		'[?let [= \$n [\$count [\$store:list-docs \$c]]]\n' +
		'[result [same [\$eq \$h \$hl]] [got \$got] [before \$before] [count \$n]]\n' +
		']]]]]]]\n')
	assert rt.exit_code == 0, 'round trip exited ${rt.exit_code}: ${rt.output} | daemon: ${xc_daemon_log(tmp)}'
	assert rt.output.contains('[same true]'), 'remote hash must be BYTE-IDENTICAL to the local embedded hash: ${rt.output}'
	assert rt.output.contains('w6-round-trip'), 'doc body must round-trip over the profile: ${rt.output}'
	assert rt.output.contains('[before true]'), 'exists must be true after put: ${rt.output}'
	assert rt.output.contains('[count 1]'), 'list-docs must report the one doc: ${rt.output}'

	// ── query pushdown + iter + delete lifecycle ─────────────────────────────
	qi := xc_run(tmp, xport, 'qi.cx', xc_lib +
		'[?let [= \$c [\$store:open "${url}"]]\n' +
		'[?let [= \$nq [\$count [\$store:query \$c "//title"]]]\n' +
		'[?let [= \$matched [\$store:query \$c "//title"]]\n' +
		'[?let [= \$ni [\$count [\$store:iter-docs \$c]]]\n' +
		'[result [nq \$nq] [matched \$matched] [ni \$ni]]\n' +
		']]]]\n')
	assert qi.exit_code == 0, 'query/iter exited ${qi.exit_code}: ${qi.output} | daemon: ${xc_daemon_log(tmp)}'
	assert qi.output.contains('[nq 1]'), 'query //title must be pushed server-side and match once: ${qi.output}'
	assert qi.output.contains('xsp-client'), 'the query match must carry the title body: ${qi.output}'
	assert qi.output.contains('[ni 1]'), 'iter-docs must stream the one doc: ${qi.output}'

	// ── aliases: authoritative daemon table, explicit absence ────────────────
	al := xc_run(tmp, xport, 'al.cx', xc_lib +
		'[?let [= \$c [\$store:open "${url}"]]\n' +
		'[?let [= \$h [\$store:put-doc \$c [cfg [v 1]]]]\n' +
		'[?let [= \$s [\$store:set-alias \$c "cfg/current" \$h]]\n' +
		'[?let [= \$g [\$store:get-alias \$c "cfg/current"]]\n' +
		'[?let [= \$n [\$count [\$store:list-aliases \$c]]]\n' +
		'[result [set-ok [\$eq \$g \$h]] [n \$n]]\n' +
		']]]]]\n')
	assert al.exit_code == 0, 'aliases exited ${al.exit_code}: ${al.output} | daemon: ${xc_daemon_log(tmp)}'
	assert al.output.contains('[set-ok true]'), 'get-alias must resolve to the set hash: ${al.output}'
	assert al.output.contains('[n 1]'), 'list-aliases must report the one alias: ${al.output}'

	// ── modify: server-side structural edit, new hash back ───────────────────
	md := xc_run(tmp, xport, 'md.cx', xc_lib +
		'[?let [= \$c [\$store:open "${url}"]]\n' +
		'[?let [= \$h [\$store:put-doc \$c [pre [body "modify-me"]]]]\n' +
		'[?let [= \$h2 [\$store:modify-doc \$c \$h [set-attr name=rev value="2"]]]\n' +
		'[?let [= \$got [\$store:get-doc-text \$c \$h2]]\n' +
		'[result [changed [\$not [\$eq \$h \$h2]]] [got \$got]]\n' +
		']]]]\n')
	assert md.exit_code == 0, 'modify exited ${md.exit_code}: ${md.output} | daemon: ${xc_daemon_log(tmp)}'
	assert md.output.contains('[changed true]'), 'modify must return a NEW hash: ${md.output}'
	assert md.output.contains("rev='2'") || md.output.contains('rev="2"'), 'the modified doc must carry the new attr: ${md.output}'

	// ── error identity: modify of an absent hash → CXER1121 VERBATIM (error
	// transparency — the profile never remaps op-layer codes); absent
	// get-doc-text stays the absence channel (§9.1.2.1), caught by [?else] ──
	ab := xc_run(tmp, xport, 'ab.cx', xc_lib +
		'[?let [= \$c [\$store:open "${url}"]]\n' +
		'[?else [\$store:get-doc-text \$c "sha2-256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"] "honest-absence"]]\n')
	assert ab.exit_code == 0, 'absence lane exited ${ab.exit_code}: ${ab.output} | daemon: ${xc_daemon_log(tmp)}'
	assert ab.output.contains('honest-absence'), 'absent get-doc-text must be the absence channel: ${ab.output}'
	me := xc_run(tmp, xport, 'me.cx', xc_lib +
		'[?let [= \$c [\$store:open "${url}"]]\n' +
		'[\$store:modify-doc \$c "sha2-256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa" [set-attr name=x value="y"]]]\n')
	assert me.output.contains('CXER1121'), 'modify of an absent hash must surface CXER1121 verbatim over the profile: ${me.output}'

	// ── delete lifecycle ──────────────────────────────────────────────────────
	dl := xc_run(tmp, xport, 'dl.cx', xc_lib +
		'[?let [= \$c [\$store:open "${url}"]]\n' +
		'[?let [= \$h [\$store:put-doc \$c [tmp [body "delete-me"]]]]\n' +
		'[?let [= \$d [\$store:delete-doc \$c \$h]]\n' +
		'[?let [= \$after [\$store:exists \$c \$h]]\n' +
		'[result [deleted \$d] [after \$after]]\n' +
		']]]]\n')
	assert dl.exit_code == 0, 'delete exited ${dl.exit_code}: ${dl.output} | daemon: ${xc_daemon_log(tmp)}'
	assert dl.output.contains('[deleted true]'), 'delete-doc must report success: ${dl.output}'
	assert dl.output.contains('[after false]'), 'exists must be false after delete: ${dl.output}'

	// ── admin: status/gc are store-level (open under floor) ──────────────────
	ad := xc_run(tmp, xport, 'ad.cx', xc_lib +
		'[?let [= \$c [\$store:open "${url}"]]\n' +
		'[?let [= \$st [\$store:status \$c]]\n' +
		'[?let [= \$gc [\$store:gc \$c]]\n' +
		'[result [st \$st] [gc \$gc]]\n' +
		']]]\n')
	assert ad.exit_code == 0, 'status/gc exited ${ad.exit_code}: ${ad.output} | daemon: ${xc_daemon_log(tmp)}'
	assert ad.output.contains('[status') || ad.output.contains('docs='), 'status must answer the porcelain element: ${ad.output}'

	// ── mounts: anonymous refused (daemon-level admin needs a DID) ───────────
	mn := xc_run(tmp, xport, 'mn.cx', xc_lib +
		'[?let [= \$c [\$store:open "${url}"]]\n' +
		'[\$store:mounts \$c]]\n')
	assert mn.output.contains('CXER5018') || mn.output.contains('DID-proven'),
		'anonymous mounts must be refused in open mode: ${mn.output}'

	// ── mounts with a mutual (DID-proven) client identity via open-opts ──────
	os.setenv('CX_STORE_XSP_CLIENT_TEST_CLI_SEED', xc_client_seed_hex, true)
	mi := xc_run(tmp, xport, 'mi.cx', xc_lib +
		'[?let [= \$c [\$store:open-opts "${url}" [map xsp-did="${xc_client_did}" xsp-seed-env="CX_STORE_XSP_CLIENT_TEST_CLI_SEED"]]]\n' +
		'[\$store:mounts \$c]]\n')
	assert mi.exit_code == 0, 'mutual mounts exited ${mi.exit_code}: ${mi.output} | daemon: ${xc_daemon_log(tmp)}'
	assert mi.output.contains('name=') && mi.output.contains('main'),
		'a DID-proven client must read the mount table: ${mi.output}'
}

fn xc_daemon_log(tmp string) string {
	return os.read_file(os.join_path(tmp, 'daemon.log')) or { '' }
}

// ── journal-over-profile (#644 / #718 item 7 / journal.md §6.1) ──────────────
// The journal rides a cx-store(+xsp):// mount: entry docs travel as objects,
// the per-stream head/entry pointers ride the daemon's AUTHORITATIVE alias
// table — all over the profile now. A SECOND attach (fresh process) rehydrates
// the chain from the daemon and verify is green; the third append continues
// the chain (the stale-tail CAS lives daemon-side, same CXER1114 identity).
fn test_xsp_client_journal_over_profile() {
	_, xport, tmp, mut proc := xc_boot()
	defer {
		xc_stop(mut proc, tmp)
	}
	url := 'cx-store+xsp://127.0.0.1:${xport}/main/'
	jlib := "[?lib 'cx-stdlib/journal' :as journal]\n"

	j1 := xc_run(tmp, xport, 'j1.cx', jlib +
		'[?let [= \$j [\$journal:open "${url}" "acme"]]\n' +
		'[?let [= \$e1 [\$journal:append \$j [do :a] {actor: "did:key:test", authority: "t-1"}]]\n' +
		'[?let [= \$e2 [\$journal:append \$j [do :b] {actor: "did:key:test", authority: "t-1"}]]\n' +
		'[?let [= \$hd [\$journal:head \$j]]\n' +
		'[?let [= \$v [\$journal:verify \$j]]\n' +
		'[result [hd \$hd] [v \$v]]\n' +
		']]]]]\n')
	assert j1.exit_code == 0, 'journal session 1 exited ${j1.exit_code}: ${j1.output} | daemon: ${xc_daemon_log(tmp)}'
	assert j1.output.contains('seq=2'), 'head must be seq 2 after two appends over the profile: ${j1.output}'
	assert j1.output.contains('valid=true'), 'the chain must verify over the profile: ${j1.output}'

	// a FRESH process re-attaches, rehydrates from the daemon, reads entry 1,
	// verifies, and CONTINUES the chain at seq 3.
	j2 := xc_run(tmp, xport, 'j2.cx', jlib +
		'[?let [= \$j [\$journal:open "${url}" "acme"]]\n' +
		'[?let [= \$rd [\$journal:read \$j 1]]\n' +
		'[?let [= \$v [\$journal:verify \$j]]\n' +
		'[?let [= \$e3 [\$journal:append \$j [do :c] {actor: "did:key:test", authority: "t-1"}]]\n' +
		'[result [rd \$rd] [v \$v] [e3 \$e3]]\n' +
		']]]]\n')
	assert j2.exit_code == 0, 'journal session 2 exited ${j2.exit_code}: ${j2.output} | daemon: ${xc_daemon_log(tmp)}'
	assert j2.output.contains(':a'), 'entry 1 must rehydrate from the daemon: ${j2.output}'
	assert j2.output.contains('valid=true'), 'the rehydrated chain must verify: ${j2.output}'
	assert j2.output.contains('seq=3'), 'the chain must continue at seq 3 across processes: ${j2.output}'
}

// ── source: vcx/tests/store_xsp_serve_test.v ──
// store_xsp_serve_test.v — BEHAVIORAL proof of the XSP STORE-PROFILE listener
// (I5 stream 4 W3; spec/03-approved/xap/xsp_store_profile.md §4.1/§4.2), following
// the fabric_serve_test.v pattern: the REAL `cx store-serve` daemon boots as a
// subprocess with the [xsp] listener enabled, and every client-side handshake
// runs through the real cx binary's $xsp:auth-* calculus (RFC 7748/8032
// fixture vectors). The wire is raw XSP frames over TCP: attach rides binary
// stream-0 frames, verbs ride TEXT frames carrying canonical CX.
//
// One boot (floor policy, sole store "main" on file://) covers:
//   verb before attach                    → CXER5010 fail-closed
//   attach offering "store xap"/"credit resume" → confirmed intersection
//                                           profiles="store" features="credit"
//                                           (read back via $xsp:auth-finish)
//   attach offering "xap" only            → CXER5010 no-common-profile refusal
//   put (ast_bin body)                    → hash BYTE-IDENTICAL to the local
//                                           embedded put of the same doc (M5)
//   get present                           → ast_bin body whose re-render
//                                           re-hashes to the address
//   get absent / bare-hex address         → present=false / CXER5017
//   delete, modify (+ verbatim CXER1121)  → op-for-op CSRP semantics
//   binary verb frame / unknown verb      → CXER5011 / CXER5012
//   list unbounded                        → N events + eos(count=N), eos flag set
//   list window=2 + credit replenish      → push stops at the window, resumes
//   query + mid-stream cancel             → eos cancelled=true
//   credit grant<1 / unknown stream       → CXER5014
//   objects-put (multihash verified)      → stored=N; mismatch → CXER5017
//   objects-have / objects-get            → missing-only / roundtrip bytes
//   refs-set CAS (all-or-nothing)         → CXER1114 verbatim on conflict
//   aliases / aliases-set (+CAS, +1121)   → explicit presence, verbatim faults
//   status / gc                           → the porcelain elements verbatim
//   session                               → restates the confirmed set
//   ping                                  → pong echoes payload verbatim
//   anonymous attach under floor          → data ops OK; mounts/config-reload
//                                           refused CXER5018; mutual client OK
//
// A second boot (test_store_xsp_authority) covers the W4 §6.1 ENFORCING
// posture: [grants …] ⇒ deny-by-default PEP ([deny] rides VERBATIM,
// CXER4700 as data; 5018 never fires), floor read grant, VC presentation
// via the M3 [attach [vp "<canonical text>"]] field AND phase=present
// (late grant), [bounds [count 2]] exhaustion → CXER4713, spend bounds
// fail-closed CXER5021, and the proof-of-possession subject rule
// (CXER-XSP-AUTH-SUBJECT).

const sx_host_did = 'did:key:z6MkiaMbhXHNA4eJVCCj8dbzKzTgYDKf6crKgHVHid1F1WCT' // RFC 8032 TEST 2

const sx_host_seed_hex = '4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb'

const sx_client_did = 'did:key:z6MktwupdmLXVVqTzCw4i46r4uGyosGXRnR3XjN4Zq7oMMsw' // RFC 8032 TEST 1

const sx_client_seed_hex = '9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60'

const sx_b_seed_hex = 'c5aa8df43f9f837bedb7442f31dcb7b166d38535076f094b85ce3a2e0b4458f7' // RFC 8032 TEST 3

const sx_b_pub_hex = 'fc51cd8e6218a1a38da47ed00230f0580816ed13ba3303ac5deb911548908025'

const sx_eph_priv_hex = '77076d0a7318a57d3c16c17251b26645df4c2f87ebc0992ab177fba51db92c2a' // RFC 7748 alice

const sx_eph_pub_hex = '8520f0098930a754748b7ddcb43ef75a0dbf3a0d26381af4eba4a98eaa9b4e6a'

const sx_nonce_hex = '0101010101010101010101010101010101010101010101010101010101010101'

// Disjoint port band (27350-27449) from fabric (27100) / http (26400) /
// xap-host (26800).
fn sx_pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 40
	return 27350 + int(salt)
}

fn sx_write(dir string, name string, content string) string {
	p := os.join_path(dir, name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

fn sx_run_cx(args string, prog string) string {
	res := os.execute('${testenv.cx_bin()} ${args} ${prog}')
	if res.exit_code != 0 {
		panic('cx helper failed (${res.exit_code}): ${res.output}')
	}
	return res.output.trim_space().trim("'")
}

// ── client-side calculus ─────────────────────────────────────────────────────

const sx_prelude = "[?lib 'cx-stdlib/xsp' :as xsp]\n[?lib 'cx-stdlib/bytes' :as bytes]\n" +
	"[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/strings' :as str]\n"

fn sx_m1_prog(endpoint string, did string, profiles string, features string) string {
	did_field := if did == '' { '' } else { 'did: "${did}", ' }
	return sx_prelude +
		'[?let [= \$m1 [\$xsp:auth-hello {${did_field}nonce: [\$bytes:from-hex "${sx_nonce_hex}"], eph: [\$bytes:from-hex "${sx_eph_pub_hex}"], endpoint: "${endpoint}", offer-profiles: "${profiles}", offer-features: "${features}"}]]\n' +
		'[\$bytes:to-base64 [\$xsp:encode [frame type=request stream=0 [payload \$m1]]]]]\n'
}

fn sx_m3_prog(m2_path string, endpoint string, did string, seed_hex string, profiles string, features string, tenant string) string {
	did_field := if did == '' { '' } else { 'did: "${did}", ' }
	key_field := if seed_hex == '' { '' } else { 'key: [\$bytes:from-hex "${seed_hex}"], ' }
	attach := if tenant == '' {
		'[attach [session mirror]]'
	} else {
		'[attach [tenant "${tenant}"] [session mirror]]'
	}
	return sx_prelude + '[?let\n' +
		'  [= \$m1 [\$xsp:auth-hello {${did_field}nonce: [\$bytes:from-hex "${sx_nonce_hex}"], eph: [\$bytes:from-hex "${sx_eph_pub_hex}"], endpoint: "${endpoint}", offer-profiles: "${profiles}", offer-features: "${features}"}]]\n' +
		'  [= \$d2 [\$xsp:decode [\$bytes:from-base64 [\$str:trim [\$io:read-file "${m2_path}"]]]]]\n' +
		'  [= \$m2 \$d2/payload]\n' +
		'  [= \$m3 [\$xsp:auth-prove \$m1 \$m2 {eph-priv: [\$bytes:from-hex "${sx_eph_priv_hex}"], ${key_field}attach: ${attach}}]]\n' +
		'  [\$bytes:to-base64 [\$xsp:encode [frame type=request stream=0 [payload \$m3]]]]]\n'
}

// sx_m3_prog_vp is sx_m3_prog with extra let-bindings (e.g. a [$vc:issue …])
// and extra [attach …] children (e.g. `[vp $cred]`) — the W4 §6.1
// presentation-in-M3 lane.
fn sx_m3_prog_vp(m2_path string, endpoint string, did string, seed_hex string, profiles string, features string, tenant string, lets string, attach_extra string) string {
	did_field := if did == '' { '' } else { 'did: "${did}", ' }
	key_field := if seed_hex == '' { '' } else { 'key: [\$bytes:from-hex "${seed_hex}"], ' }
	tenant_part := if tenant == '' { '' } else { '[tenant "${tenant}"] ' }
	return sx_prelude + "[?lib 'cx-stdlib/vc' :as vc]\n" + '[?let\n' + lets +
		'  [= \$m1 [\$xsp:auth-hello {${did_field}nonce: [\$bytes:from-hex "${sx_nonce_hex}"], eph: [\$bytes:from-hex "${sx_eph_pub_hex}"], endpoint: "${endpoint}", offer-profiles: "${profiles}", offer-features: "${features}"}]]\n' +
		'  [= \$d2 [\$xsp:decode [\$bytes:from-base64 [\$str:trim [\$io:read-file "${m2_path}"]]]]]\n' +
		'  [= \$m2 \$d2/payload]\n' +
		'  [= \$m3 [\$xsp:auth-prove \$m1 \$m2 {eph-priv: [\$bytes:from-hex "${sx_eph_priv_hex}"], ${key_field}attach: [attach ${tenant_part}${attach_extra}[session mirror]]}]]\n' +
		'  [\$bytes:to-base64 [\$xsp:encode [frame type=request stream=0 [payload \$m3]]]]]\n'
}

// sxt_attach_vp runs the attach with presentation material in the M3.
fn sxt_attach_vp(port int, tmp string, tag string, did string, seed_hex string, profiles string, features string, tenant string, lets string, attach_extra string) (&SxtChan, SxtFrame) {
	endpoint := 'tcp://127.0.0.1:${port}'
	conn := net.dial_tcp('127.0.0.1:${port}') or { panic('dial ${port}: ${err}') }
	mut ch := &SxtChan{
		conn: conn
	}
	m1_prog := sx_write(tmp, 'm1-${tag}.cx', sx_m1_prog(endpoint, did, profiles, features))
	sxt_send(mut ch, base64.decode(sx_run_cx('', m1_prog)))
	m2 := sxt_read_frame(mut ch, 5 * time.second) or { panic('no M2 (${tag})') }
	assert m2.ftype == 3, 'M2 is not a reply frame (${tag}): type ${m2.ftype}'
	m2_path := sx_write(tmp, 'm2-${tag}.b64', base64.encode(m2.raw))
	m3_prog := sx_write(tmp, 'm3-${tag}.cx', sx_m3_prog_vp(m2_path, endpoint, did, seed_hex,
		profiles, features, tenant, lets, attach_extra))
	sxt_send(mut ch, base64.decode(sx_run_cx('--allow-read', m3_prog)))
	m4 := sxt_read_frame(mut ch, 5 * time.second) or { panic('no M4 (${tag})') }
	if m4.ftype == 3 {
		sxt_drain_advert(mut ch, tag)
	}
	return ch, m4
}

// sx_present_frame builds a post-attach [xsp-auth phase=present [vp "…"]]
// binary request through the shipped codec — the vp is the CANONICAL TEXT of
// the [vp [vc …]…] value in a single-scalar field (the §4.4a shape rule +
// the L165 lossless-lane rule: signed content never rides data-bin).
fn sx_present_frame(tmp string, tag string, lets string) []u8 {
	return sx_present_frame_vp(tmp, tag, lets, '[vp \$cred]')
}

// sx_present_frame_vp is sx_present_frame with the [vp …] value expression
// under the test's control — R3.3 needs a [vp] that carries no [vc] (the
// malformed-presentation post-attach lane). `lets` may be empty when the
// vp_expr references no bindings.
fn sx_present_frame_vp(tmp string, tag string, lets string, vp_expr string) []u8 {
	body := if lets == '' { '' } else { '[?let\n' + lets + '  [= \$vpt [\$cx:emit ${vp_expr}]]\n' }
	prog := if lets == '' {
		sx_prelude + "[?lib 'cx-stdlib/vc' :as vc]\n" +
			'[?let [= \$vpt [\$cx:emit ${vp_expr}]]\n' +
			'  [\$bytes:to-base64 [\$xsp:encode [frame type=request stream=0 [payload [xsp-auth phase=present [vp \$vpt]]]]]]]\n'
	} else {
		sx_prelude + "[?lib 'cx-stdlib/vc' :as vc]\n" + body +
			'  [\$bytes:to-base64 [\$xsp:encode [frame type=request stream=0 [payload [xsp-auth phase=present [vp \$vpt]]]]]]]\n'
	}
	return base64.decode(sx_run_cx('', sx_write(tmp, 'present-${tag}.cx', prog)))
}

// sx_finish_prog re-runs the client transcript and verifies M4 through
// $xsp:auth-finish, printing "profiles|features" from the confirmed set —
// the §4.4a negotiation read back through the REAL initiator calculus.
fn sx_finish_prog(m2_path string, m4_path string, endpoint string, did string, seed_hex string, profiles string, features string, tenant string) string {
	did_field := if did == '' { '' } else { 'did: "${did}", ' }
	key_field := if seed_hex == '' { '' } else { 'key: [\$bytes:from-hex "${seed_hex}"], ' }
	return sx_prelude + '[?let\n' +
		'  [= \$m1 [\$xsp:auth-hello {${did_field}nonce: [\$bytes:from-hex "${sx_nonce_hex}"], eph: [\$bytes:from-hex "${sx_eph_pub_hex}"], endpoint: "${endpoint}", offer-profiles: "${profiles}", offer-features: "${features}"}]]\n' +
		'  [= \$d2 [\$xsp:decode [\$bytes:from-base64 [\$str:trim [\$io:read-file "${m2_path}"]]]]]\n' +
		'  [= \$m2 \$d2/payload]\n' +
		'  [= \$d4 [\$xsp:decode [\$bytes:from-base64 [\$str:trim [\$io:read-file "${m4_path}"]]]]]\n' +
		'  [= \$m4 \$d4/payload]\n' +
		'  [= \$done [\$xsp:auth-finish \$m1 \$m2 \$m4 {eph-priv: [\$bytes:from-hex "${sx_eph_priv_hex}"]}]]\n' +
		'  [\$str:join ([\$text \$done/confirmed/@profiles], [\$text \$done/confirmed/@features]) "|"]]\n'
}

// ── frame codec (V side) ─────────────────────────────────────────────────────

struct SxtFrame {
	ftype   u8
	stream  u64
	flags   u8
	payload []u8
	raw     []u8
}

fn sxt_frame_text(ftype u8, stream u64, text string, eos bool) []u8 {
	pl := text.bytes()
	mut buf := []u8{cap: 17 + pl.len}
	buf << u8(0x01)
	buf << ftype
	for i := 7; i >= 0; i-- {
		buf << u8(stream >> (u64(i) * 8))
	}
	mut flags := u8(0)
	if eos {
		flags |= 0x02
	}
	buf << flags
	buf << u8(0)
	buf << u8(0)
	buf << u8(pl.len >> 24)
	buf << u8(pl.len >> 16)
	buf << u8(pl.len >> 8)
	buf << u8(pl.len)
	buf << pl
	return buf
}

// sxt_frame_credit builds a type-8 credit frame whose payload is the data-bin
// integer grant — built through the cx binary so the data-bin bytes are the
// shipped codec's, not a hand imitation.
fn sxt_frame_credit(tmp string, tag string, stream u64, grant int) []u8 {
	prog := sx_write(tmp, 'credit-${tag}.cx', sx_prelude +
		'[\$bytes:to-base64 [\$xsp:encode [frame type=credit stream=${stream} [payload ${grant}]]]]\n')
	return base64.decode(sx_run_cx('', prog))
}

struct SxtChan {
mut:
	conn  &net.TcpConn = unsafe { nil }
	carry []u8
	// the §7a.1 [store-advert …] pushed after M4 (drained by sxt_attach so
	// request/reply choreography stays aligned; lanes assert on it here).
	advert string
}

// sxt_drain_advert consumes the stream-0 advert event a successful attach
// pushes (§7a.1) and stashes its payload on the channel.
fn sxt_drain_advert(mut ch SxtChan, tag string) {
	ev := sxt_read_frame(mut ch, 5 * time.second) or { panic('no store-advert (${tag})') }
	assert ev.ftype == 2 && ev.stream == 0, 'advert frame (${tag}): type ${ev.ftype} stream ${ev.stream}'
	ch.advert = ev.payload.bytestr()
	assert ch.advert.starts_with('[store-advert '), 'advert payload (${tag}): ${ch.advert}'
}

fn (mut ch SxtChan) close() {
	ch.conn.close() or {}
}

fn sxt_read_frame(mut ch SxtChan, deadline time.Duration) ?SxtFrame {
	ch.conn.set_read_timeout(deadline)
	mut buf := ch.carry.clone()
	mut need := 13
	for {
		for buf.len >= need {
			plen := int(u16(buf[11]) << 8 | u16(buf[12]))
			if need == 13 {
				need = 17 + plen
				continue
			}
			mut paylen := 0
			if buf.len >= 13 + plen + 4 {
				mut pl32 := u32(0)
				for i in 13 + plen .. 13 + plen + 4 {
					pl32 = (pl32 << 8) | u32(buf[i])
				}
				paylen = int(pl32)
				total := 17 + plen + paylen
				if buf.len >= total {
					mut stream := u64(0)
					for i in 2 .. 10 {
						stream = (stream << 8) | u64(buf[i])
					}
					ch.carry = buf[total..].clone()
					return SxtFrame{
						ftype:   buf[1]
						stream:  stream
						flags:   buf[10]
						payload: buf[13 + plen + 4..total].clone()
						raw:     buf[..total].clone()
					}
				}
				need = total
			} else {
				need = 13 + plen + 4
			}
			break
		}
		mut tmp := []u8{len: 4096}
		n := ch.conn.read(mut tmp) or {
			ch.carry = buf
			return none
		}
		if n <= 0 {
			ch.carry = buf
			return none
		}
		buf << tmp[..n]
	}
	return none
}

fn sxt_send(mut ch SxtChan, frame []u8) {
	ch.conn.write(frame) or { panic('frame write: ${err}') }
}

fn sxt_request(mut ch SxtChan, stream u64, text string) SxtFrame {
	sxt_send(mut ch, sxt_frame_text(1, stream, text, false))
	return sxt_read_frame(mut ch, 5 * time.second) or {
		panic('no reply to request on stream ${stream}: ${text}')
	}
}

// ── attach choreography ──────────────────────────────────────────────────────

fn sxt_attach(port int, tmp string, tag string, did string, seed_hex string, profiles string, features string, tenant string) (&SxtChan, SxtFrame) {
	endpoint := 'tcp://127.0.0.1:${port}'
	conn := net.dial_tcp('127.0.0.1:${port}') or { panic('dial ${port}: ${err}') }
	mut ch := &SxtChan{
		conn: conn
	}
	m1_prog := sx_write(tmp, 'm1-${tag}.cx', sx_m1_prog(endpoint, did, profiles, features))
	sxt_send(mut ch, base64.decode(sx_run_cx('', m1_prog)))
	m2 := sxt_read_frame(mut ch, 5 * time.second) or { panic('no M2 (${tag})') }
	assert m2.ftype == 3, 'M2 is not a reply frame (${tag}): type ${m2.ftype}'
	m2_path := sx_write(tmp, 'm2-${tag}.b64', base64.encode(m2.raw))
	m3_prog := sx_write(tmp, 'm3-${tag}.cx', sx_m3_prog(m2_path, endpoint, did, seed_hex,
		profiles, features, tenant))
	sxt_send(mut ch, base64.decode(sx_run_cx('--allow-read', m3_prog)))
	m4 := sxt_read_frame(mut ch, 5 * time.second) or { panic('no M4 (${tag})') }
	if m4.ftype == 3 {
		sxt_drain_advert(mut ch, tag)
	}
	return ch, m4
}

// ── daemon boot ──────────────────────────────────────────────────────────────

fn sxt_boot() (int, int, string, &os.Process) {
	return sxt_boot_cfg(0, '')
}

fn sxt_boot_cfg(offset int, grants string) (int, int, string, &os.Process) {
	return sxt_boot_xsp(offset, sx_host_did, 'CX_STORE_XSP_SEED', sx_host_seed_hex, grants,
		'', [])
}

// sxt_boot_xsp boots one `cx store-serve` daemon with a parameterized [xsp]
// identity and extra [xsp] subsections (grants/revocations/peers) — the W5
// two-daemon peer choreography needs distinct identities per daemon and an
// extra allow-net for the outbound peer dial. `stores` overrides the mount
// set ([] = the sole "main" store): the R3.2 CXER5013 ambiguity lane needs a
// daemon that mounts MORE than one store.
fn sxt_boot_xsp(offset int, identity_did string, seed_env string, seed_hex string, xsp_extra string, extra_net string, stores []string) (int, int, string, &os.Process) {
	cxbin := testenv.cx_bin()
	// offset < 1000 = a band offset over the salted base; ≥ 1000 = an
	// ABSOLUTE port (the two-daemon peer test pins both daemons off one
	// salt draw so their ports can never collide across draws).
	port := if offset >= 1000 { offset } else { sx_pick_port() + offset }
	xport := port + 1
	tmp := os.join_path(os.temp_dir(), 'cx-store-xsp-test-${os.getpid()}-${offset}')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp) or { panic('mkdir ${tmp}: ${err}') }
	mut stores_rows := '[store name="main" url="file://${tmp}/store"]'
	if stores.len > 0 {
		mut rows := []string{}
		for s in stores {
			rows << '[store name="${s}" url="file://${tmp}/store-${s}"]'
		}
		stores_rows = rows.join(' ')
	}
	cfg := '[cxstore-service
  [bind addr="127.0.0.1:${port}"]
  [stores ${stores_rows}]
  [xsp enabled=true addr="127.0.0.1:${xport}"
    [identity did="${identity_did}" seed-env="${seed_env}"]
    [policy mode=floor floor="guest"]${xsp_extra}]
  [workers query-pool=2]]'
	cfg_path := sx_write(tmp, 'cxstore.service.cx', cfg)
	os.setenv(seed_env, seed_hex, true)
	net_extra := if extra_net == '' { '' } else { ' --allow-net=${extra_net}' }
	mut proc := os.new_process('/bin/sh')
	proc.set_args(['-c',
		'exec "${cxbin}" store-serve --config "${cfg_path}" --exit-on-stdin-eof --allow-read --allow-write --allow-net=127.0.0.1:${port} --allow-net=127.0.0.1:${xport}${net_extra} --allow-env >"${tmp}/daemon.log" 2>&1'])
	proc.set_redirect_stdio() // stdin pipe = the #648 tether
	proc.run()
	mut up := false
	for _ in 0 .. 100 {
		time.sleep(100 * time.millisecond)
		r := http.get('http://127.0.0.1:${port}/cx-store/v1/ready') or { continue }
		if r.status_code == 200 && r.body.contains('[accepting true]') {
			up = true
			break
		}
	}
	if !up {
		proc.signal_kill()
		out := os.read_file(os.join_path(tmp, 'daemon.log')) or { '' }
		panic('store-serve never came up: ${out}')
	}
	return port, xport, tmp, proc
}

// sx_body_hex builds the framed ast_bin body hex for a doc, through the REAL
// codec ([$ast:emit-bytes …] — the same bytes the server's bin_to_doc reads).
fn sx_body_hex(tmp string, tag string, doc string) string {
	prog := sx_write(tmp, 'body-${tag}.cx',
		"[?lib 'cx-stdlib/bytes' :as bytes]\n[\$bytes:to-hex [\$ast:emit-bytes ${doc}]]\n")
	return sx_run_cx('', prog)
}

// sx_local_hash puts the same doc into a LOCAL embedded store and returns the
// content address — the M5 byte-identical-address oracle.
fn sx_local_hash(tmp string, tag string, doc string) string {
	prog := sx_write(tmp, 'local-${tag}.cx', "[?lib 'cx-stdlib/store' :as store]\n" +
		'[?let [= \$s [\$store:open "mem://oracle-${tag}"]] [\$store:put-doc \$s ${doc}]]\n')
	return sx_run_cx('', prog)
}

// sx_render_body re-renders a wire ast_bin body (hex) to canonical text.
fn sx_render_body(tmp string, tag string, body_hex string) string {
	prog := sx_write(tmp, 'render-${tag}.cx',
		"[?lib 'cx-stdlib/bytes' :as bytes]\n[\$cx:emit [\$ast:parse-bytes [\$bytes:from-hex \"${body_hex}\"]]]\n")
	return sx_run_cx('', prog)
}

// sx_decode_reply decodes a full XSP reply frame (raw bytes) and returns the
// canonical text of the payload's first child — for asserting attrs on a
// data-bin (binary) reply like [presented compiled=N inert=K], whose integer
// attr values are wire-encoded and cannot be substring-matched as text.
fn sx_decode_reply(tmp string, tag string, raw []u8) string {
	b64 := base64.encode(raw)
	prog := sx_write(tmp, 'decode-${tag}.cx', sx_prelude +
		'[?let [= \$f [\$xsp:decode [\$bytes:from-base64 "${b64}"]]]\n' +
		'  [\$cx:emit [\$first \$f/payload/*]]]\n')
	return sx_run_cx('', prog)
}

// sx_attr pulls attr="…" or attr=value off a rendered envelope (string hack,
// good enough for assertion plumbing).
fn sx_attr(payload string, name string) string {
	mut idx := payload.index('${name}="') or {
		i2 := payload.index('${name}=') or { return '' }
		rest := payload[i2 + name.len + 1..]
		// canonical renders quote with ' — read the quoted span
		if rest.len > 0 && rest[0] == `'` {
			e := rest[1..].index("'") or { return '' }
			return rest[1..1 + e]
		}
		mut end := rest.len
		for j, c in rest {
			if c == ` ` || c == `]` {
				end = j
				break
			}
		}
		return rest[..end]
	}
	rest := payload[idx + name.len + 2..]
	end := rest.index('"') or { return '' }
	return rest[..end]
}

fn sx_body_hex_of(payload string) string {
	idx := payload.index('[body::bytes 0x') or { return '' }
	rest := payload[idx + '[body::bytes 0x'.len..]
	end := rest.index(']') or { return '' }
	return rest[..end]
}

// ── the one boot, all lanes ──────────────────────────────────────────────────

fn test_store_xsp_profile_listener() {
	port, xport, tmp, mut proc := sxt_boot()
	defer {
		proc.signal_kill()
		proc.wait()
		os.rmdir_all(tmp) or {}
	}

	// ── verb before attach: fail-closed CXER5010 ──
	{
		conn := net.dial_tcp('127.0.0.1:${xport}') or { panic('dial: ${err}') }
		mut ch := &SxtChan{
			conn: conn
		}
		r := sxt_request(mut ch, 9, '[status]')
		assert r.ftype == 7, 'expected error frame, got type ${r.ftype}'
		assert r.payload.bytestr().contains('CXER5010'), 'verb before attach: ${r.payload.bytestr()}'
		ch.close()
	}

	// ── no common profile: an xap-only offer is refused at attach ──
	{
		mut ch, m4 := sxt_attach(xport, tmp, 'xaponly', sx_client_did, sx_client_seed_hex,
			'xap', 'credit', 'main')
		assert m4.ftype == 7, 'xap-only attach should be refused'
		// binary error frame: the code is inside the data-bin payload — check raw
		assert m4.raw.bytestr().contains('CXER5010'), 'no-common-profile: ${m4.raw.bytestr()}'
		ch.close()
	}

	// ── mutual attach (sole-store shorthand: NO tenant in M3) ──
	mut ch, m4 := sxt_attach(xport, tmp, 'main', sx_client_did, sx_client_seed_hex,
		'store xap', 'credit resume', '')
	assert m4.ftype == 3, 'attach failed: ${m4.raw.bytestr()}'
	defer {
		ch.close()
	}

	// the confirmed intersection, verified through the real initiator calculus
	{
		m2_path := os.join_path(tmp, 'm2-main.b64')
		m4_path := sx_write(tmp, 'm4-main.b64', base64.encode(m4.raw))
		fin := sx_write(tmp, 'finish-main.cx', sx_finish_prog(m2_path, m4_path, 'tcp://127.0.0.1:${xport}',
			sx_client_did, sx_client_seed_hex, 'store xap', 'credit resume', ''))
		got := sx_run_cx('--allow-read', fin)
		assert got == 'store|credit', 'confirmed sets: ${got}'
	}

	// ── ping echoes payload verbatim (§5.1) ──
	{
		sxt_send(mut ch, sxt_frame_text(5, 77, 'echo-me', false))
		pong := sxt_read_frame(mut ch, 5 * time.second) or { panic('no pong') }
		assert pong.ftype == 6 && pong.stream == 77, 'pong header: ${pong.ftype}/${pong.stream}'
		assert pong.payload.bytestr() == 'echo-me', 'pong payload: ${pong.payload.bytestr()}'
	}

	// ── capabilities: the profile advert ──
	{
		r := sxt_request(mut ch, 11, '[capabilities]')
		assert r.ftype == 3
		p := r.payload.bytestr()
		assert p.contains('[profile "store"]') && p.contains('"config-reload"')
			&& p.contains('"journal-fold"') && p.contains('"put-blob"')
			&& p.contains('[features "credit store-delta store-feed store-journal"]'), 'capabilities: ${p}'
	}

	// ── put: the wire address is BYTE-IDENTICAL to the local embedded put ──
	doc1 := '[order id=1 total=99.5]'
	body1 := sx_body_hex(tmp, 'doc1', doc1)
	local1 := sx_local_hash(tmp, 'doc1', doc1)
	mut hash1 := ''
	{
		r := sxt_request(mut ch, 21, '[put [body::bytes 0x${body1}]]')
		assert r.ftype == 3, 'put: ${r.payload.bytestr()}'
		p := r.payload.bytestr()
		hash1 = sx_attr(p, 'hash')
		assert hash1 == local1, 'wire ${hash1} ≠ local ${local1} (M5 byte-identity)'
		assert sx_attr(p, 'stored') == 'true', 'first put should store: ${p}'
	}
	// content-dedup: the same doc again is stored=false, same address
	{
		r := sxt_request(mut ch, 22, '[put [body::bytes 0x${body1}]]')
		p := r.payload.bytestr()
		assert sx_attr(p, 'hash') == hash1 && sx_attr(p, 'stored') == 'false', 'dedup: ${p}'
	}

	// ── get present: the body re-renders to text whose canonical re-put is the
	//    same address (the lane's byte-exactness obligation) ──
	{
		r := sxt_request(mut ch, 23, '[get hash="${hash1}"]')
		p := r.payload.bytestr()
		assert r.ftype == 3 && sx_attr(p, 'present') == 'true', 'get: ${p}'
		body := sx_body_hex_of(p)
		assert body != '', 'get carried no ast_bin body: ${p}'
		rendered := sx_render_body(tmp, 'get1', body)
		relocal := sx_local_hash(tmp, 'roundtrip', rendered)
		assert relocal == hash1, 'roundtrip re-hash ${relocal} ≠ ${hash1}'
	}

	// ── get absent is DATA; a bare-hex address is CXER5017 ──
	{
		r := sxt_request(mut ch, 24, '[get hash="sha2-256:${'ab'.repeat(32)}"]')
		assert r.ftype == 3 && sx_attr(r.payload.bytestr(), 'present') == 'false', 'absent: ${r.payload.bytestr()}'
		r2 := sxt_request(mut ch, 25, '[get hash="${'ab'.repeat(32)}"]')
		assert r2.ftype == 7 && r2.payload.bytestr().contains('CXER5017'), 'bare hex: ${r2.payload.bytestr()}'
	}

	// ── wrong lane: a binary verb frame is CXER5011; unknown verb CXER5012 ──
	{
		// a request frame with the payload-binary flag set is the wrong lane —
		// the payload bytes are NOT valid data-bin, but the lane check must fire
		// before any payload decode is attempted. Build it through the shipped
		// codec so it IS valid data-bin, proving the refusal is the LANE rule.
		prog := sx_write(tmp, 'binverb.cx', sx_prelude +
			'[\$bytes:to-base64 [\$xsp:encode [frame type=request stream=26 [payload [status]]]]]\n')
		sxt_send(mut ch, base64.decode(sx_run_cx('', prog)))
		r := sxt_read_frame(mut ch, 5 * time.second) or { panic('no lane refusal') }
		assert r.ftype == 7 && r.payload.bytestr().contains('CXER5011'), 'binary verb: ${r.payload.bytestr()}'
		r2 := sxt_request(mut ch, 27, '[frobnicate]')
		assert r2.ftype == 7 && r2.payload.bytestr().contains('CXER5012'), 'unknown verb: ${r2.payload.bytestr()}'
	}

	// ── modify: happy path + verbatim CXER1121 on an unknown source ──
	mut hash2 := ''
	{
		r := sxt_request(mut ch, 28, '[modify hash="${hash1}" [action [set-attr name="total" value=100.0]]]')
		p := r.payload.bytestr()
		assert r.ftype == 3, 'modify: ${p}'
		hash2 = sx_attr(p, 'new-hash')
		assert hash2 != '' && hash2 != hash1, 'modify new-hash: ${p}'
		r2 := sxt_request(mut ch, 29, '[modify hash="sha2-256:${'cd'.repeat(32)}" [action [set-attr name="x" value=1]]]')
		assert r2.ftype == 7 && r2.payload.bytestr().contains('CXER1121'), 'modify missing rides verbatim: ${r2.payload.bytestr()}'
	}

	// ── delete round-trip ──
	{
		r := sxt_request(mut ch, 30, '[delete hash="${hash2}"]')
		assert sx_attr(r.payload.bytestr(), 'deleted') == 'true', 'delete: ${r.payload.bytestr()}'
		r2 := sxt_request(mut ch, 31, '[get hash="${hash2}"]')
		assert sx_attr(r2.payload.bytestr(), 'present') == 'false', 'deleted doc still present'
	}

	// ── streams: put two more docs (3 total), list unbounded → 3 events + eos ──
	// nested [line] children: store-query matches DESCENDANTS (the same
	// semantics as the local $store:query — parity by construction)
	doc2 := '[order id=2 total=10.0 [line sku="a" qty=1]]'
	doc3 := '[invoice id=3 total=7.25 [line sku="b" qty=2]]'
	sxt_request(mut ch, 32, '[put [body::bytes 0x${sx_body_hex(tmp, 'doc2', doc2)}]]')
	sxt_request(mut ch, 33, '[put [body::bytes 0x${sx_body_hex(tmp, 'doc3', doc3)}]]')
	{
		sxt_send(mut ch, sxt_frame_text(1, 40, '[list]', false))
		mut hashes := []string{}
		mut saw_eos := false
		for _ in 0 .. 4 {
			f := sxt_read_frame(mut ch, 5 * time.second) or { panic('list stream starved') }
			assert f.ftype == 2 && f.stream == 40, 'list frame: ${f.ftype}/${f.stream}'
			p := f.payload.bytestr()
			if f.flags & 0x02 != 0 {
				assert p.contains('[eos count=3]'), 'list eos: ${p}'
				saw_eos = true
				break
			}
			hashes << p
		}
		assert saw_eos && hashes.len == 3, 'list: ${hashes.len} events, eos=${saw_eos}'
	}

	// ── credit governance: window=2 stops the push; a credit frame resumes ──
	{
		sxt_send(mut ch, sxt_frame_text(1, 41, '[list window=2]', false))
		f1 := sxt_read_frame(mut ch, 5 * time.second) or { panic('windowed list e1') }
		f2 := sxt_read_frame(mut ch, 5 * time.second) or { panic('windowed list e2') }
		assert f1.ftype == 2 && f2.ftype == 2 && f2.flags & 0x02 == 0
		// window exhausted: NOTHING more arrives until credit
		if starved := sxt_read_frame(mut ch, 700 * time.millisecond) {
			panic('window not enforced: got type ${starved.ftype} ${starved.payload.bytestr()}')
		}
		sxt_send(mut ch, sxt_frame_credit(tmp, 'grant41', 41, 1))
		f3 := sxt_read_frame(mut ch, 5 * time.second) or { panic('post-credit event') }
		assert f3.ftype == 2 && f3.flags & 0x02 == 0, 'third event: ${f3.payload.bytestr()}'
		eos := sxt_read_frame(mut ch, 5 * time.second) or { panic('post-credit eos') }
		assert eos.flags & 0x02 != 0 && eos.payload.bytestr().contains('[eos count=3]'), 'eos: ${eos.payload.bytestr()}'
	}

	// ── credit refusals: grant<1 and unknown stream → CXER5014 ──
	{
		sxt_send(mut ch, sxt_frame_credit(tmp, 'zero', 42, 0))
		r := sxt_read_frame(mut ch, 5 * time.second) or { panic('no credit refusal') }
		assert r.ftype == 7 && r.payload.bytestr().contains('CXER5014'), 'grant 0: ${r.payload.bytestr()}'
		sxt_send(mut ch, sxt_frame_credit(tmp, 'orphan', 4242, 5))
		r2 := sxt_read_frame(mut ch, 5 * time.second) or { panic('no orphan-credit refusal') }
		assert r2.ftype == 7 && r2.payload.bytestr().contains('CXER5014'), 'orphan: ${r2.payload.bytestr()}'
	}

	// ── query + mid-stream cancel → eos cancelled=true ──
	{
		sxt_send(mut ch, sxt_frame_text(1, 43, '[query path="//line" window=1]', false))
		f1 := sxt_read_frame(mut ch, 5 * time.second) or { panic('query e1') }
		assert f1.ftype == 2 && f1.payload.bytestr().contains('[result doc='), 'query event (L97 flat tuple): ${f1.payload.bytestr()}'
		sxt_send(mut ch, sxt_frame_text(4, 43, '', false)) // cancel
		eos := sxt_read_frame(mut ch, 5 * time.second) or { panic('no cancel eos') }
		assert eos.flags & 0x02 != 0 && eos.payload.bytestr().contains('cancelled=true'), 'cancel: ${eos.payload.bytestr()}'
	}
	// query needs path=
	{
		r := sxt_request(mut ch, 44, '[query]')
		assert r.ftype == 7 && r.payload.bytestr().contains('CXER5011'), 'query no path: ${r.payload.bytestr()}'
	}

	// ── the object wire: verified put, missing-only have, roundtrip get ──
	obj := 'hello object wire'.bytes()
	digest := sha256.sum256(obj)
	mh := '1220' + digest.hex()
	absent_mh := '1220' + sha256.sum256('never stored'.bytes()).hex()
	{
		r := sxt_request(mut ch, 50, '[objects-put [o h::bytes=0x${mh} [bytes::bytes 0x${obj.hex()}]]]')
		assert r.ftype == 3 && sx_attr(r.payload.bytestr(), 'stored') == '1', 'objects-put: ${r.payload.bytestr()}'
		// a lying address is refused whole (never trust-the-label)
		r2 := sxt_request(mut ch, 51, '[objects-put [o h::bytes=0x${absent_mh} [bytes::bytes 0x${obj.hex()}]]]')
		assert r2.ftype == 7 && r2.payload.bytestr().contains('CXER5017'), 'objects-put mismatch: ${r2.payload.bytestr()}'
		// have: only the missing address comes back
		r3 := sxt_request(mut ch, 52, '[objects-have [o h::bytes=0x${mh}] [o h::bytes=0x${absent_mh}]]')
		p3 := r3.payload.bytestr()
		assert !p3.contains(mh) && p3.contains(absent_mh), 'objects-have: ${p3}'
		// get: the exact bytes come back under the same multihash
		r4 := sxt_request(mut ch, 53, '[objects-get [o h::bytes=0x${mh}] [o h::bytes=0x${absent_mh}]]')
		p4 := r4.payload.bytestr()
		assert p4.contains('h::bytes=0x${mh}') && p4.contains('[bytes::bytes 0x${obj.hex()}]')
			&& !p4.contains(absent_mh), 'objects-get: ${p4}'
		// a malformed multihash is CXER5017
		r5 := sxt_request(mut ch, 54, '[objects-have [o h::bytes=0xdead]]')
		assert r5.ftype == 7 && r5.payload.bytestr().contains('CXER5017'), 'bad mh: ${r5.payload.bytestr()}'
	}

	// ── refs: CAS all-or-nothing on the pointer layer, CXER1114 verbatim ──
	{
		// expect=0x (must-not-exist) → applies
		r := sxt_request(mut ch, 55, '[refs-set [r key="head" root::bytes=0x${mh} expect::bytes=0x]]')
		assert r.ftype == 3 && sx_attr(r.payload.bytestr(), 'set') == '1', 'refs-set: ${r.payload.bytestr()}'
		// read it back
		r2 := sxt_request(mut ch, 56, '[refs [k key="head"] [k key="ghost"]]')
		p2 := r2.payload.bytestr()
		assert p2.contains('key="head" present=true root::bytes=0x${mh}')
			&& p2.contains('key="ghost" present=false'), 'refs: ${p2}'
		// stale expect → CXER1114, and the batch applies NOTHING
		r3 := sxt_request(mut ch, 57, '[refs-set [r key="head" root::bytes=0x${absent_mh} expect::bytes=0x]]')
		assert r3.ftype == 7 && r3.payload.bytestr().contains('CXER1114'), 'refs CAS: ${r3.payload.bytestr()}'
		r4 := sxt_request(mut ch, 58, '[refs [k key="head"]]')
		assert r4.payload.bytestr().contains('root::bytes=0x${mh}'), 'conflict must not advance: ${r4.payload.bytestr()}'
	}

	// ── aliases: explicit presence; CAS; verbatim 1121 on a missing target ──
	{
		r := sxt_request(mut ch, 60, '[aliases-set [a name="latest" hash="${hash1}" expect=""]]')
		assert r.ftype == 3 && sx_attr(r.payload.bytestr(), 'set') == '1', 'aliases-set: ${r.payload.bytestr()}'
		r2 := sxt_request(mut ch, 61, '[aliases [k name="latest"] [k name="nope"]]')
		p2 := r2.payload.bytestr()
		assert p2.contains('name="latest" present=true hash="${hash1}"')
			&& p2.contains('name="nope" present=false'), 'aliases: ${p2}'
		r3 := sxt_request(mut ch, 62, '[aliases-set [a name="latest" hash="${hash1}" expect=""]]')
		assert r3.ftype == 7 && r3.payload.bytestr().contains('CXER1114'), 'alias CAS: ${r3.payload.bytestr()}'
		r4 := sxt_request(mut ch, 63, '[aliases-set [a name="dangling" hash="sha2-256:${'ef'.repeat(32)}"]]')
		assert r4.ftype == 7 && r4.payload.bytestr().contains('CXER1121'), 'alias target rides verbatim: ${r4.payload.bytestr()}'
	}

	// ── porcelain admin ops ──
	{
		r := sxt_request(mut ch, 70, '[status]')
		assert r.ftype == 3 && r.payload.bytestr().starts_with('[status'), 'status: ${r.payload.bytestr()}'
		r2 := sxt_request(mut ch, 71, '[gc]')
		assert r2.ftype == 3 && r2.payload.bytestr().starts_with('[gc-result'), 'gc: ${r2.payload.bytestr()}'
	}

	// ── daemon-level verbs: allowed for the DID-proven client ──
	{
		r := sxt_request(mut ch, 72, '[mounts]')
		p := r.payload.bytestr()
		assert r.ftype == 3 && p.contains('[mount name="main"'), 'mounts: ${p}'
		// an unchanged config re-reads clean: a REPLY (never an error frame)
		// carrying the §3.13 report with applied=false / no changed sections.
		r2 := sxt_request(mut ch, 73, '[config-reload]')
		p2 := r2.payload.bytestr()
		assert r2.ftype == 3 && p2.starts_with('[config-reload applied='), 'config-reload: ${p2}'
	}

	// ── session restates the confirmed set (surface 2, never extends) ──
	{
		r := sxt_request(mut ch, 74, '[session]')
		p := r.payload.bytestr()
		assert p.contains('profiles="store"') && p.contains('features="heartbeat credit"'), 'session: ${p}'
	}

	// ── anonymous attach under the floor: data ops OK, admin refused 5018 ──
	{
		mut ach, am4 := sxt_attach(xport, tmp, 'anon', '', '', 'store', 'credit', 'main')
		assert am4.ftype == 3, 'anonymous attach under floor failed: ${am4.raw.bytestr()}'
		r := sxt_request(mut ach, 80, '[get hash="${hash1}"]')
		assert r.ftype == 3 && sx_attr(r.payload.bytestr(), 'present') == 'true', 'anon get: ${r.payload.bytestr()}'
		r2 := sxt_request(mut ach, 81, '[mounts]')
		assert r2.ftype == 7 && r2.payload.bytestr().contains('CXER5018'), 'anon mounts: ${r2.payload.bytestr()}'
		r3 := sxt_request(mut ach, 82, '[config-reload]')
		assert r3.ftype == 7 && r3.payload.bytestr().contains('CXER5018'), 'anon reload: ${r3.payload.bytestr()}'
		ach.close()
	}

	// ── W4 §5: the change feed ──
	// feed on a session that did not confirm store-feed → un-negotiated
	{
		r := sxt_request(mut ch, 90, '[feed]')
		assert r.ftype == 7 && r.payload.bytestr().contains('CXER5012'), 'un-negotiated feed: ${r.payload.bytestr()}'
	}
	mut fboot := ''
	mut pos4 := ''
	doc4 := '[order id=4 total=4.0]'
	mut hash4 := ''
	{
		// a feed-capable session: tail subscription, cross-connection events,
		// never-coalesced discriminator, credit governance, cancel.
		mut chf, fm4 := sxt_attach(xport, tmp, 'feed', sx_client_did, sx_client_seed_hex,
			'store', 'credit resume store-feed store-delta', '')
		assert fm4.ftype == 3, 'feed attach: ${fm4.raw.bytestr()}'
		// rung refuse-to-lie + bad plane + bad boot cursor, all typed at subscribe
		rr := sxt_request(mut chf, 91, '[feed rung=":snapshot-diff"]')
		assert rr.ftype == 7 && rr.payload.bytestr().contains('CXER5019'), 'rung refusal: ${rr.payload.bytestr()}'
		rp := sxt_request(mut chf, 92, '[feed [planes "docs bogus"]]')
		assert rp.ftype == 7 && rp.payload.bytestr().contains('CXER5019'), 'bad plane: ${rp.payload.bytestr()}'
		rb := sxt_request(mut chf, 93, '[feed [from boot="nope" [s plane="docs" pos=1]]]')
		assert rb.ftype == 7 && rb.payload.bytestr().contains('CXER5020'), 'cross-boot cursor: ${rb.payload.bytestr()}'
		// the live tail: window=3
		fs := sxt_request(mut chf, 94, '[feed window=3]')
		fsp := fs.payload.bytestr()
		assert fs.ftype == 3 && fsp.contains('rung=":complete-ordered"')
			&& fsp.contains('[head-set boot="'), 'feed-sub: ${fsp}'
		fboot = sx_attr(fsp, 'boot')
		assert fboot != '', 'no boot token: ${fsp}'
		// two puts from the OTHER connection = two distinct insert frames
		// (∂ never coalesces), then an alias advance as the third
		hash4 = sx_attr(sxt_request(mut ch, 95, '[put [body::bytes 0x${sx_body_hex(tmp,
			'doc4', doc4)}]]').payload.bytestr(), 'hash')
		doc5 := '[order id=5 total=5.0]'
		hash5 := sx_attr(sxt_request(mut ch, 96, '[put [body::bytes 0x${sx_body_hex(tmp,
			'doc5', doc5)}]]').payload.bytestr(), 'hash')
		e1 := sxt_read_frame(mut chf, 5 * time.second) or { panic('feed e1') }
		p1 := e1.payload.bytestr()
		assert e1.ftype == 2 && e1.stream == 94 && p1.contains('[insert plane="docs"')
			&& p1.contains('hash="${hash4}"'), 'feed insert 1: ${p1}'
		pos4 = sx_attr(p1, 'pos')
		e2 := sxt_read_frame(mut chf, 5 * time.second) or { panic('feed e2') }
		assert e2.payload.bytestr().contains('hash="${hash5}"'), 'feed insert 2: ${e2.payload.bytestr()}'
		sxt_request(mut ch, 97, '[aliases-set [a name="feedtag" hash="${hash4}"]]')
		e3 := sxt_read_frame(mut chf, 5 * time.second) or { panic('feed e3') }
		p3 := e3.payload.bytestr()
		assert p3.contains('[advance plane="aliases" name="feedtag"')
			&& p3.contains('hash="${hash4}"'), 'alias advance: ${p3}'
		// window exhausted: a delete lands in the lineage but nothing arrives
		sxt_request(mut ch, 98, '[delete hash="${hash5}"]')
		if starved := sxt_read_frame(mut chf, 700 * time.millisecond) {
			panic('feed window not enforced: ${starved.payload.bytestr()}')
		}
		sxt_send(mut chf, sxt_frame_credit(tmp, 'feedgrant', 94, 2))
		e4 := sxt_read_frame(mut chf, 5 * time.second) or { panic('feed e4 post-credit') }
		p4 := e4.payload.bytestr()
		assert p4.contains('[retract plane="docs"') && p4.contains('hash="${hash5}"'), 'doc retract: ${p4}'
		// cancel terminates with eos cancelled=true (a feed has no natural end)
		sxt_send(mut chf, sxt_frame_text(4, 94, '', false))
		eos := sxt_read_frame(mut chf, 5 * time.second) or { panic('feed cancel eos') }
		assert eos.flags & 0x02 != 0 && eos.payload.bytestr().contains('cancelled=true'), 'feed cancel: ${eos.payload.bytestr()}'
		chf.close()
	}
	{
		// resume from a HEAD-SET cursor: replays strictly above the floor, in
		// position order, then goes live; bodies ride under store-delta; a
		// refs advance carries its E3 position + multihash root.
		mut chr, rm4 := sxt_attach(xport, tmp, 'resume', sx_client_did, sx_client_seed_hex,
			'store', 'credit store-feed store-delta', '')
		assert rm4.ftype == 3
		from_pos := pos4.i64() - 1
		fs := sxt_request(mut chr, 100, '[feed bodies=true [planes "docs refs"] [from boot="${fboot}" [s plane="docs" pos=${from_pos}] [s plane="refs" name="head" pos=1]]]')
		assert fs.ftype == 3, 'resume feed-sub: ${fs.payload.bytestr()}'
		r1 := sxt_read_frame(mut chr, 5 * time.second) or { panic('resume r1') }
		p1 := r1.payload.bytestr()
		assert p1.contains('hash="${hash4}"') && sx_attr(p1, 'pos') == pos4
			&& p1.contains('[body::bytes 0x'), 'resume replay w/ body: ${p1}'
		r2 := sxt_read_frame(mut chr, 5 * time.second) or { panic('resume r2') }
		assert r2.payload.bytestr().contains('[insert plane="docs"'), 'resume r2: ${r2.payload.bytestr()}'
		r3 := sxt_read_frame(mut chr, 5 * time.second) or { panic('resume r3') }
		p3r := r3.payload.bytestr()
		// R3.4 (audit F-26): a deleted doc replayed under bodies=true carries
		// NO body — the retract is body-absent even on a body-bearing sub
		// (there is no content to serve for a deleted address). Strengthened
		// from a bare substring to pin the body-absence + the retracted hash.
		assert p3r.contains('[retract plane="docs"') && p3r.contains('hash="')
			&& !p3r.contains('[body::bytes'), 'deleted-replay must be body-absent: ${p3r}'
		// live continuation: a wire refs-set lands as [advance plane="refs"]
		// with the dense per-name E3 position and the multihash root
		obj2 := 'feed object'.bytes()
		mh2 := '1220' + sha256.sum256(obj2).hex()
		sxt_request(mut ch, 101, '[objects-put [o h::bytes=0x${mh2} [bytes::bytes 0x${obj2.hex()}]]]')
		sxt_request(mut ch, 102, '[refs-set [r key="feedhead" root::bytes=0x${mh2} expect::bytes=0x]]')
		r4 := sxt_read_frame(mut chr, 5 * time.second) or { panic('resume r4 refs') }
		p4 := r4.payload.bytestr()
		assert p4.contains('[advance plane="refs" name="feedhead" pos=1')
			&& p4.contains('root::bytes=0x${mh2}'), 'refs advance: ${p4}'
		chr.close()
	}
	{
		// bodies=true without the store-delta token → typed refusal
		mut chb, bm4 := sxt_attach(xport, tmp, 'nobodies', sx_client_did, sx_client_seed_hex,
			'store', 'credit store-feed', '')
		assert bm4.ftype == 3
		r := sxt_request(mut chb, 110, '[feed bodies=true]')
		assert r.ftype == 7 && r.payload.bytestr().contains('CXER5019'), 'bodies w/o store-delta: ${r.payload.bytestr()}'
		chb.close()
	}

	// ── W5 §7a.1: the signed, generation-bound advert (pushed after M4) ──
	{
		assert ch.advert.contains('generation=0'), 'advert generation: ${ch.advert}'
		assert ch.advert.contains('[head-set boot="'), 'advert head-set: ${ch.advert}'
		assert ch.advert.contains('[guarantees ":at-least-once :gapless :linearizable-ref :monotonic-reads :prefix-consistent :read-your-writes"]'), 'advert guarantees: ${ch.advert}'
		assert ch.advert.contains('signer="${sx_host_did}"'), 'advert signer: ${ch.advert}'
		sig := sx_attr(ch.advert, 'sig')
		assert sig.len == 128, 'advert sig: ${ch.advert}'
		// the signature verifies under the daemon's identity key over the
		// canonical [store-advert-canonical …] rebuild (the §7a.1 recipe) —
		// checked through the REAL $crypto:ed25519-verify
		idx := ch.advert.index(' signer="') or { panic('advert has no signer: ${ch.advert}') }
		canon_text := ch.advert[..idx].replace('[store-advert ', '[store-advert-canonical ') + ']'
		canon_path := sx_write(tmp, 'advert-canon.txt', canon_text)
		// RFC 8032 TEST-2 public key (the daemon identity's)
		host_pub := '3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c'
		vprog := sx_write(tmp, 'advert-verify.cx', "[?lib 'cx-stdlib/bytes' :as bytes]\n[?lib 'cx-stdlib/crypto' :as crypto]\n[?lib 'cx-stdlib/io' :as io]\n[?lib 'cx-stdlib/strings' :as str]\n" +
			'[?let\n' + '  [= \$t [\$str:trim [\$io:read-file "${canon_path}"]]]\n' +
			'  [= \$c [\$cx:canonical \$t]]\n' +
			'  [\$crypto:ed25519-verify [\$bytes:from-hex "${host_pub}"] \$c [\$bytes:from-hex "${sig}"]]]\n')
		got := sx_run_cx('--allow-read', vprog)
		assert got == 'true', 'advert signature must verify: ${got}'
		// capabilities RESTATES generation + guarantees (one truth, two surfaces)
		r := sxt_request(mut ch, 120, '[capabilities]')
		p := r.payload.bytestr()
		assert sx_attr(p, 'generation') == '0' && !p.contains('[generation')
			&& p.contains('[guarantees ":at-least-once'), 'capabilities must restate generation as the ATTR (one shape, R3.14): ${p}'
	}

	// ── W5 §7b.1: erase — the tombstone, the feed act, redaction, supersede ──
	mut hash6 := ''
	mut root6 := ''
	{
		doc6 := '[order id=6 total=6.0 [subject "erase-me"]]'
		hash6 = sx_attr(sxt_request(mut ch, 121, '[put [body::bytes 0x${sx_body_hex(tmp,
			'doc6', doc6)}]]').payload.bytestr(), 'hash')
		assert hash6 != ''
		// tail-subscribe FIRST so the erase act is observed as ∂
		mut chf2, f2m4 := sxt_attach(xport, tmp, 'feed2', sx_client_did, sx_client_seed_hex,
			'store', 'credit store-feed', '')
		assert f2m4.ftype == 3
		fs := sxt_request(mut chf2, 122, '[feed [planes "docs"]]')
		assert fs.ftype == 3, 'erase-feed sub: ${fs.payload.bytestr()}'
		// the erase: delete-grade, attributed; the actor is the session principal
		r := sxt_request(mut ch, 123, '[erase hash="${hash6}" authority="gdpr-17" request="shred-t1"]')
		p := r.payload.bytestr()
		// §5.0 shape: hash= erased= deduped=? ONLY — the request attribution
		// rides the tombstone + the feed act (both asserted below), never
		// this reply (R3.14 conformance).
		assert r.ftype == 3 && sx_attr(p, 'erased') == 'true' && !p.contains('request='), 'erase reply shape: ${p}'
		// the §5.3 [erase …] notification — the shred-request AS journal data
		// on the feed, attribution riding in the act
		e := sxt_read_frame(mut chf2, 5 * time.second) or { panic('no erase act on the feed') }
		pe := e.payload.bytestr()
		assert pe.contains('[erase plane="docs"') && pe.contains('hash="${hash6}"')
			&& pe.contains('actor="${sx_client_did}"') && pe.contains('authority="gdpr-17"')
			&& pe.contains('request="shred-t1"'), 'erase act: ${pe}'
		sxt_send(mut chf2, sxt_frame_text(4, 122, '', false))
		sxt_read_frame(mut chf2, 5 * time.second) or { panic('erase-feed cancel eos') }
		chf2.close()
		// get answers the typed tombstone VERBATIM (canonical text — the
		// stored evidence, quoted as canonical quotes) — never present=false
		g := sxt_request(mut ch, 124, '[get hash="${hash6}"]')
		gp := g.payload.bytestr()
		assert g.ftype == 3 && gp.starts_with('[erased ') && sx_attr(gp, 'hash') == hash6
			&& sx_attr(gp, 'request') == 'shred-t1', 'erased get: ${gp}'
		root6 = sx_attr(gp, 'root')
		assert root6.len == 64, 'tombstone root: ${gp}'
		// the discriminator survives the object wire: the former root answers
		// erased=true on objects-get and stays MISSING on objects-have
		ro := sxt_request(mut ch, 125, '[objects-get [o h::bytes=0x1220${root6}]]')
		assert ro.payload.bytestr().contains('h::bytes=0x1220${root6} erased=true'), 'objects-get erased: ${ro.payload.bytestr()}'
		rh := sxt_request(mut ch, 126, '[objects-have [o h::bytes=0x1220${root6}]]')
		assert rh.payload.bytestr().contains('0x1220${root6}'), 'erased root must stay missing on have: ${rh.payload.bytestr()}'
		// idempotent: the second erase is deduped, never a second act
		r2 := sxt_request(mut ch, 127, '[erase hash="${hash6}"]')
		p2 := r2.payload.bytestr()
		assert sx_attr(p2, 'erased') == 'false' && sx_attr(p2, 'deduped') == 'true', 'erase dedup: ${p2}'
	}
	{
		// a bodies=true REPLAY over the erased insert carries redacted=1 (the
		// §5.3 visible-count rule's first producer) — never a silent bodyless
		mut chr2, r2m4 := sxt_attach(xport, tmp, 'replay2', sx_client_did, sx_client_seed_hex,
			'store', 'credit store-feed store-delta', '')
		assert r2m4.ftype == 3
		fs := sxt_request(mut chr2, 130, '[feed bodies=true [planes "docs"] [from]]')
		assert fs.ftype == 3, 'redaction replay sub: ${fs.payload.bytestr()}'
		mut saw_redacted := false
		mut saw_erase_act := false
		for _ in 0 .. 30 {
			f := sxt_read_frame(mut chr2, 5 * time.second) or { break }
			fp := f.payload.bytestr()
			if fp.contains('[insert plane="docs"') && fp.contains('hash="${hash6}"') {
				assert fp.contains('redacted=1') && !fp.contains('[body::bytes'), 'erased insert replay: ${fp}'
				saw_redacted = true
			}
			if fp.contains('[erase plane="docs"') && fp.contains('hash="${hash6}"') {
				saw_erase_act = true
				break // the erase act follows its insert in-stream
			}
		}
		assert saw_redacted, 'replay never delivered the redacted insert'
		assert saw_erase_act, 'replay never delivered the erase act'
		sxt_send(mut chr2, sxt_frame_text(4, 130, '', false))
		sxt_read_frame(mut chr2, 5 * time.second) or { panic('replay cancel eos') }
		chr2.close()
	}
	{
		// a later put of the same content SUPERSEDES the tombstone (§7b.1)
		doc6 := '[order id=6 total=6.0 [subject "erase-me"]]'
		rp := sxt_request(mut ch, 131, '[put [body::bytes 0x${sx_body_hex(tmp, 'doc6b', doc6)}]]')
		assert sx_attr(rp.payload.bytestr(), 'hash') == hash6
			&& sx_attr(rp.payload.bytestr(), 'stored') == 'true', 'supersede put: ${rp.payload.bytestr()}'
		g := sxt_request(mut ch, 132, '[get hash="${hash6}"]')
		assert sx_attr(g.payload.bytestr(), 'present') == 'true', 'superseded get: ${g.payload.bytestr()}'
	}

	// ── W5 §7a.1 F3: an APPLIED reload re-advertises with the new generation ──
	{
		cfg_path := os.join_path(tmp, 'cxstore.service.cx')
		cfg := os.read_file(cfg_path) or { panic('read config') }
		os.write_file(cfg_path, cfg.replace('[workers query-pool=2]]',
			'[timeouts read-ms=29000]\n  [workers query-pool=2]]')) or { panic('write config') }
		r := sxt_request(mut ch, 140, '[config-reload]')
		p := r.payload.bytestr()
		assert r.ftype == 3 && sx_attr(p, 'applied') == 'true' && sx_attr(p, 'generation') == '1', 'reload: ${p}'
		adv := sxt_read_frame(mut ch, 5 * time.second) or { panic('no F3 re-advert') }
		assert adv.ftype == 2 && adv.stream == 0, 'F3 advert frame: ${adv.ftype}/${adv.stream}'
		ap := adv.payload.bytestr()
		assert ap.starts_with('[store-advert generation=1'), 'F3 advert: ${ap}'
	}
}

// ── W4 §6.1: the enforcing posture — grants, PEP, presentations, bounds ─────
//
// A second boot with [grants …] configured: deny-by-default over the session
// authority basis; the [deny …] value rides VERBATIM; presentations compile
// via the M3 [attach [vp "…"]] text field or phase=present; [bounds [count]]
// exhausts to CXER4713; spend bounds fail closed at presentation (CXER5021);
// a chain whose terminal subject is not the session principal is refused
// (CXER-XSP-AUTH-SUBJECT); CXER5018 never fires under grants.
fn test_store_xsp_authority() {
	grants := '\n    [grants [grant did="${sx_client_did}" caps="read write delete admin"] [grant floor=true caps="read"]]'
	_, xport, tmp, mut proc := sxt_boot_cfg(50, grants)
	defer {
		proc.signal_kill()
		proc.wait()
		os.rmdir_all(tmp) or {}
	}
	b_did := sx_run_cx('', sx_write(tmp, 'bdid.cx', "[?lib 'cx-stdlib/did' :as did]\n[?lib 'cx-stdlib/bytes' :as bytes]\n[\$did:key-create [\$bytes:from-hex \"${sx_b_pub_hex}\"]]\n"))

	// A: granted mutual client — the full class set; the 5018 gate is gone.
	mut cha, am4 := sxt_attach(xport, tmp, 'ga', sx_client_did, sx_client_seed_hex, 'store',
		'credit', 'main')
	assert am4.ftype == 3, 'granted attach: ${am4.raw.bytestr()}'
	defer {
		cha.close()
	}
	doc := '[order id=9 total=1.5]'
	r := sxt_request(mut cha, 20, '[put [body::bytes 0x${sx_body_hex(tmp, 'gdoc', doc)}]]')
	assert r.ftype == 3, 'granted put: ${r.payload.bytestr()}'
	hash := sx_attr(r.payload.bytestr(), 'hash')
	rm := sxt_request(mut cha, 21, '[mounts]')
	assert rm.ftype == 3 && rm.payload.bytestr().contains('[mount name="main"'), 'granted mounts (PEP admin): ${rm.payload.bytestr()}'

	// B: floor session — the floor read grant only; denies ride VERBATIM.
	{
		mut chf, fm4 := sxt_attach(xport, tmp, 'gfloor', '', '', 'store', 'credit', 'main')
		assert fm4.ftype == 3, 'floor attach under grants: ${fm4.raw.bytestr()}'
		rg := sxt_request(mut chf, 30, '[get hash="${hash}"]')
		assert rg.ftype == 3 && sx_attr(rg.payload.bytestr(), 'present') == 'true', 'floor read: ${rg.payload.bytestr()}'
		rp := sxt_request(mut chf, 31, '[put [body::bytes 0x${sx_body_hex(tmp, 'gdoc2',
			doc)}]]')
		p := rp.payload.bytestr()
		assert rp.ftype == 7 && p.contains('CXER4700') && p.contains('no-grant'), 'floor put deny: ${p}'
		rmm := sxt_request(mut chf, 32, '[mounts]')
		pm := rmm.payload.bytestr()
		assert rmm.ftype == 7 && pm.contains('CXER4700') && !pm.contains('CXER5018'), 'floor mounts = PEP deny, not 5018: ${pm}'
		chf.close()
	}

	vc_lets := '  [= \$claim [delegation id="d-vc-1" [tenant main] [from [principal "${sx_client_did}"]] [to [agent "${b_did}"]] [capabilities [read]] [bounds [count 2]]]]\n' +
		'  [= \$cred [\$vc:issue "${sx_client_did}" [\$bytes:from-hex "${sx_client_seed_hex}"] "${b_did}" \$claim]]\n'

	// C: deny-by-default, then a post-attach presentation (late grant, §5.1)
	//    with [bounds [count 2]] — two reads, then CXER4713.
	{
		mut chb, bm4 := sxt_attach(xport, tmp, 'gb', b_did, sx_b_seed_hex, 'store', 'credit',
			'main')
		assert bm4.ftype == 3, 'clientB attach: ${bm4.raw.bytestr()}'
		r0 := sxt_request(mut chb, 40, '[get hash="${hash}"]')
		assert r0.ftype == 7 && r0.payload.bytestr().contains('no-grant'), 'pre-present deny: ${r0.payload.bytestr()}'
		sxt_send(mut chb, sx_present_frame(tmp, 'chain', vc_lets))
		pr := sxt_read_frame(mut chb, 5 * time.second) or { panic('no present reply') }
		assert pr.ftype == 3 && pr.raw.bytestr().contains('presented'), 'present: ${pr.raw.bytestr()}'
		r1 := sxt_request(mut chb, 41, '[get hash="${hash}"]')
		assert r1.ftype == 3, 'post-present get 1: ${r1.payload.bytestr()}'
		r2 := sxt_request(mut chb, 42, '[get hash="${hash}"]')
		assert r2.ftype == 3, 'post-present get 2: ${r2.payload.bytestr()}'
		r3 := sxt_request(mut chb, 43, '[get hash="${hash}"]')
		p3 := r3.payload.bytestr()
		assert r3.ftype == 7 && p3.contains('CXER4713') && p3.contains('budget-exhausted')
			&& p3.contains('count'), 'count exhaustion: ${p3}'
		chb.close()
	}

	// D: proof of possession — a chain whose terminal subject is another DID.
	{
		mut chd, dm4 := sxt_attach(xport, tmp, 'gd', b_did, sx_b_seed_hex, 'store', 'credit',
			'main')
		assert dm4.ftype == 3
		bad_lets := '  [= \$claim [delegation id="d-vc-2" [tenant main] [from [principal "${sx_client_did}"]] [to [agent "${sx_client_did}"]] [capabilities [read]]]]\n' +
			'  [= \$cred [\$vc:issue "${sx_client_did}" [\$bytes:from-hex "${sx_client_seed_hex}"] "${sx_client_did}" \$claim]]\n'
		sxt_send(mut chd, sx_present_frame(tmp, 'subj', bad_lets))
		er := sxt_read_frame(mut chd, 5 * time.second) or { panic('no subject refusal') }
		assert er.ftype == 7 && er.raw.bytestr().contains('CXER-XSP-AUTH-SUBJECT'), 'subject mismatch: ${er.raw.bytestr()}'
		chd.close()
	}

	// E: spend bounds fail closed at presentation (unmeterable at v1, §6.1).
	{
		mut che, em4 := sxt_attach(xport, tmp, 'ge', b_did, sx_b_seed_hex, 'store', 'credit',
			'main')
		assert em4.ftype == 3
		spend_lets := '  [= \$claim [delegation id="d-vc-3" [tenant main] [from [principal "${sx_client_did}"]] [to [agent "${b_did}"]] [capabilities [read]] [bounds [spend 5.0 :currency :usd :per "1d"]]]]\n' +
			'  [= \$cred [\$vc:issue "${sx_client_did}" [\$bytes:from-hex "${sx_client_seed_hex}"] "${b_did}" \$claim]]\n'
		sxt_send(mut che, sx_present_frame(tmp, 'spend', spend_lets))
		er := sxt_read_frame(mut che, 5 * time.second) or { panic('no spend refusal') }
		assert er.ftype == 7 && er.raw.bytestr().contains('CXER5021'), 'spend fail-closed: ${er.raw.bytestr()}'
		che.close()
	}

	// F: the M3-carried presentation — compiles INSIDE the attach (text field).
	{
		m3_lets := vc_lets + '  [= \$vpt [\$cx:emit [vp \$cred]]]\n'
		mut chm, fm4 := sxt_attach_vp(xport, tmp, 'gm3vp', b_did, sx_b_seed_hex, 'store',
			'credit', '', m3_lets, '[vp \$vpt] ')
		assert fm4.ftype == 3, 'M3-vp attach: ${fm4.raw.bytestr()}'
		rg := sxt_request(mut chm, 60, '[get hash="${hash}"]')
		assert rg.ftype == 3, 'M3-vp get: ${rg.payload.bytestr()}'
		chm.close()
	}

	// G (register R3.1 / audit F-20): a presentation in the WRONG CARRIAGE —
	// the nested [vp [vc …]] ELEMENT the spec names as the likely mistake —
	// must refuse the attach LOUDLY (§6.1 CXER5021), never attach a quietly
	// under-authorized session with zero compiled authority.
	{
		mut chg, gm4 := sxt_attach_vp(xport, tmp, 'gm3vpnested', b_did, sx_b_seed_hex,
			'store', 'credit', '', vc_lets, '[vp \$cred] ')
		assert gm4.ftype == 7, 'nested-vp M3 must REFUSE the attach (got frame type ${gm4.ftype}): ${gm4.raw.bytestr()}'
		assert gm4.raw.bytestr().contains('CXER5021'), 'nested-vp refusal must be the §6.1 CXER5021 identity: ${gm4.raw.bytestr()}'
		chg.close()
	}
}

// ── R3.3 (audit F-24): authority presentation-fault lanes, each over a real
// daemon through the profile listener ──────────────────────────────────────
// The presentation compiler (store_xsp_authority.v sx_present_locked) has
// five distinct refusal/degrade outcomes the audit found code-verified but
// wire-unguarded. Every lane here drives the SHIPPED [xsp-auth phase=present]
// frame against a booted daemon:
//   - floor-cannot-present → CXER5021 (§5.1: a non-mutual session has no
//     principal to bind presented authority to)
//   - malformed [vp] with no [vc] → CXER5021 (post-attach sibling of the
//     R3.1 M3-carriage refusal; the fault is the empty carriage)
//   - unrecognized ROOT → [presented compiled=0 inert=K], NOT an error
//     (N-TRUST-1: a foreign chain conjures no authority but never voids the
//     session)
//   - cross-tenant delegation → CXER4805 (§5.3: the tenant partition is a
//     FAULT, never inert)
//   - escalation (a link naming a parent the issuer does not hold) →
//     CXER4703 (§5.2 four-axis attenuation)
fn test_store_xsp_authority_presentation_faults() {
	grants := '\n    [grants [grant did="${sx_client_did}" caps="read write delete admin"] [grant floor=true caps="read"]]'
	_, xport, tmp, mut proc := sxt_boot_cfg(70, grants)
	defer {
		proc.signal_kill()
		proc.wait()
		os.rmdir_all(tmp) or {}
	}
	b_did := sx_run_cx('', sx_write(tmp, 'bdid.cx', "[?lib 'cx-stdlib/did' :as did]\n[?lib 'cx-stdlib/bytes' :as bytes]\n[\$did:key-create [\$bytes:from-hex \"${sx_b_pub_hex}\"]]\n"))
	// an UNRECOGNIZED root identity — no grant names it, it is not the daemon
	unk_did := sx_run_cx('', sx_write(tmp, 'unkdid.cx', "[?lib 'cx-stdlib/did' :as did]\n[?lib 'cx-stdlib/bytes' :as bytes]\n[\$did:key-create [\$bytes:from-hex \"${sx_b2_pub_hex}\"]]\n"))

	// ── floor-cannot-present: a floor (anonymous, non-mutual) session that
	//    presents a well-formed vp is refused CXER5021 ──
	{
		mut chf, fm4 := sxt_attach(xport, tmp, 'flpres', '', '', 'store', 'credit', 'main')
		assert fm4.ftype == 3, 'floor attach: ${fm4.raw.bytestr()}'
		lets := '  [= \$claim [delegation id="d-fl" [tenant main] [from [principal "${sx_client_did}"]] [to [agent "${b_did}"]] [capabilities [read]]]]\n' +
			'  [= \$cred [\$vc:issue "${sx_client_did}" [\$bytes:from-hex "${sx_client_seed_hex}"] "${b_did}" \$claim]]\n'
		sxt_send(mut chf, sx_present_frame(tmp, 'flpres', lets))
		er := sxt_read_frame(mut chf, 5 * time.second) or { panic('no floor-present refusal') }
		assert er.ftype == 7 && er.raw.bytestr().contains('CXER5021'), 'floor cannot present: ${er.raw.bytestr()}'
		chf.close()
	}

	// ── malformed [vp] carrying no [vc] → CXER5021 (post-attach) ──
	{
		mut chm, mm4 := sxt_attach(xport, tmp, 'malvp', b_did, sx_b_seed_hex, 'store', 'credit',
			'main')
		assert mm4.ftype == 3, 'malformed-vp attach: ${mm4.raw.bytestr()}'
		sxt_send(mut chm, sx_present_frame_vp(tmp, 'malvp', '', '[vp [notavc x=1]]'))
		er := sxt_read_frame(mut chm, 5 * time.second) or { panic('no malformed-vp refusal') }
		assert er.ftype == 7 && er.raw.bytestr().contains('CXER5021'), 'malformed vp: ${er.raw.bytestr()}'
		chm.close()
	}

	// ── unrecognized ROOT → [presented compiled=0 inert=1], session survives ──
	{
		mut chi, im4 := sxt_attach(xport, tmp, 'inert', b_did, sx_b_seed_hex, 'store', 'credit',
			'main')
		assert im4.ftype == 3, 'inert attach: ${im4.raw.bytestr()}'
		lets := '  [= \$claim [delegation id="d-unk" [tenant main] [from [principal "${unk_did}"]] [to [agent "${b_did}"]] [capabilities [read]]]]\n' +
			'  [= \$cred [\$vc:issue "${unk_did}" [\$bytes:from-hex "${sx_b2_seed_hex}"] "${b_did}" \$claim]]\n'
		sxt_send(mut chi, sx_present_frame(tmp, 'inert', lets))
		pr := sxt_read_frame(mut chi, 5 * time.second) or { panic('no inert reply') }
		assert pr.ftype == 3, 'unrecognized root must be a reply, not an error frame: ${pr.raw.bytestr()}'
		presented := sx_decode_reply(tmp, 'inert', pr.raw)
		assert sx_attr(presented, 'compiled') == '0' && sx_attr(presented, 'inert') == '1', 'unrecognized root must compile nothing, inert 1: ${presented}'
		// the session SURVIVES the inert presentation: it still answers verbs
		// (b_did holds no grant, so the op denies with PEP CXER4700 — the
		// point is the connection is alive and enforcing, never torn down).
		rg := sxt_request(mut chi, 50, '[status]')
		assert rg.ftype == 7 && rg.payload.bytestr().contains('CXER4700'), 'session must survive inert presentation and keep enforcing: ${rg.payload.bytestr()}'
		chi.close()
	}

	// ── cross-tenant delegation → CXER4805 (a FAULT, never inert) ──
	{
		mut chx, xm4 := sxt_attach(xport, tmp, 'xten', b_did, sx_b_seed_hex, 'store', 'credit',
			'main')
		assert xm4.ftype == 3, 'cross-tenant attach: ${xm4.raw.bytestr()}'
		lets := '  [= \$claim [delegation id="d-xt" [tenant other] [from [principal "${sx_client_did}"]] [to [agent "${b_did}"]] [capabilities [read]]]]\n' +
			'  [= \$cred [\$vc:issue "${sx_client_did}" [\$bytes:from-hex "${sx_client_seed_hex}"] "${b_did}" \$claim]]\n'
		sxt_send(mut chx, sx_present_frame(tmp, 'xten', lets))
		er := sxt_read_frame(mut chx, 5 * time.second) or { panic('no cross-tenant refusal') }
		assert er.ftype == 7 && er.raw.bytestr().contains('CXER4805'), 'cross-tenant fault: ${er.raw.bytestr()}'
		chx.close()
	}

	// ── escalation: a delegation naming an [attenuates …] parent the issuer
	//    does not hold → CXER4703 ──
	{
		mut che, em4 := sxt_attach(xport, tmp, 'esc', b_did, sx_b_seed_hex, 'store', 'credit',
			'main')
		assert em4.ftype == 3, 'escalation attach: ${em4.raw.bytestr()}'
		lets := '  [= \$claim [delegation id="d-esc" [tenant main] [from [principal "${sx_client_did}"]] [to [agent "${b_did}"]] [capabilities [read]] [attenuates "ghost-parent-never-held"]]]\n' +
			'  [= \$cred [\$vc:issue "${sx_client_did}" [\$bytes:from-hex "${sx_client_seed_hex}"] "${b_did}" \$claim]]\n'
		sxt_send(mut che, sx_present_frame(tmp, 'esc', lets))
		er := sxt_read_frame(mut che, 5 * time.second) or { panic('no escalation refusal') }
		assert er.ftype == 7 && er.raw.bytestr().contains('CXER4703'), 'escalation refused: ${er.raw.bytestr()}'
		che.close()
	}
}

// ── R3.6 (audit F-22): the F3 re-advert is pushed DIRECTLY by the reload
// verb, not only by the ≤250ms sweeper generation-watch ─────────────────────
// The spec (§7a.1 F3) mandates BOTH: a direct push from the reload verb on
// this listener AND the sweeper watch for reloads landing through the OTHER
// listeners. The audit found only the sweeper implemented. Deterministic
// (non-timing) discriminator: the direct push enqueues the advert INSIDE the
// config-reload handler — so a ping sent immediately after the reload reply
// pongs AFTER the advert. With a sweeper-only impl the ping pongs FIRST and
// the advert trails (whenever the ≤250ms tick lands).
fn test_store_xsp_config_reload_direct_advert() {
	port, xport, tmp, mut proc := sxt_boot()
	defer {
		proc.signal_kill()
		proc.wait()
		os.rmdir_all(tmp) or {}
	}
	_ = port
	mut ch, m4 := sxt_attach(xport, tmp, 'reloadadv', sx_client_did, sx_client_seed_hex, 'store',
		'credit', 'main')
	assert m4.ftype == 3, 'reload-advert attach: ${m4.raw.bytestr()}'
	defer {
		ch.close()
	}
	// change the config so the reload bumps the generation
	cfg_path := os.join_path(tmp, 'cxstore.service.cx')
	cfg := os.read_file(cfg_path) or { panic('read config') }
	os.write_file(cfg_path, cfg.replace('[workers query-pool=2]]',
		'[timeouts read-ms=28000]\n  [workers query-pool=2]]')) or { panic('write config') }
	r := sxt_request(mut ch, 200, '[config-reload]')
	rp := r.payload.bytestr()
	assert r.ftype == 3 && sx_attr(rp, 'applied') == 'true' && sx_attr(rp, 'generation') == '1', 'reload: ${rp}'
	// immediately probe with a ping; the DIRECT advert must already be queued
	// ahead of the pong (it was enqueued synchronously in the reload handler)
	sxt_send(mut ch, sxt_frame_text(5, 201, 'after-reload', false))
	f1 := sxt_read_frame(mut ch, 5 * time.second) or { panic('no frame after reload+ping') }
	assert f1.ftype == 2 && f1.stream == 0 && f1.payload.bytestr().starts_with('[store-advert generation=1'), 'the F3 advert must be pushed DIRECTLY by the reload verb (ahead of the pong), not by the sweeper: got ftype=${f1.ftype} stream=${f1.stream} ${f1.payload.bytestr()}'
	f2 := sxt_read_frame(mut ch, 5 * time.second) or { panic('no pong after advert') }
	assert f2.ftype == 6 && f2.stream == 201 && f2.payload.bytestr() == 'after-reload', 'pong must follow the direct advert: ftype=${f2.ftype} stream=${f2.stream}'
}

// ── R3.4 (audit F-26): code-verified but regression-unguarded behaviors ─────
// Deterministic single-daemon wire lanes. (The delete-replay body-absence
// assert lives in test_store_xsp_profile_listener's resume block — R3.4
// strengthened it there. The peer wrong-DID pin and origin-folds-own-journal
// lanes live in test_store_xsp_peer, alongside the machinery they need.)
fn test_store_xsp_wire_regression_guards() {
	grants := '\n    [grants [grant did="${sx_client_did}" caps="read write delete admin"]]'
	_, xport, tmp, mut proc := sxt_boot_cfg(80, grants)
	defer {
		proc.signal_kill()
		proc.wait()
		os.rmdir_all(tmp) or {}
	}
	b_did := sx_run_cx('', sx_write(tmp, 'bdid.cx', "[?lib 'cx-stdlib/did' :as did]\n[?lib 'cx-stdlib/bytes' :as bytes]\n[\$did:key-create [\$bytes:from-hex \"${sx_b_pub_hex}\"]]\n"))

	// seed one doc through the admin client
	mut cha, am4 := sxt_attach(xport, tmp, 'rga', sx_client_did, sx_client_seed_hex, 'store',
		'credit store-feed store-delta', 'main')
	assert am4.ftype == 3, 'admin attach: ${am4.raw.bytestr()}'
	defer {
		cha.close()
	}
	hash := sx_attr(sxt_request(mut cha, 10, '[put [body::bytes 0x${sx_body_hex(tmp, 'rgdoc',
		'[order id=42 total=4.2]')}]]').payload.bytestr(), 'hash')
	assert hash != ''

	// ── rate retry-after ON THE XSP WIRE: a presented [bounds [rate 1 :per
	//    "1h"]] delegation exhausts after one read; the CXER4713 error frame
	//    carries a positive [retry-after …] (distinct from the count-bounds
	//    lane, which never replenishes and emits no retry-after). The HTTP/CSRP
	//    429 Retry-After is covered separately (store_wire_wave4_test); this is
	//    the profile-wire shape. ──
	{
		mut chr, rm4 := sxt_attach(xport, tmp, 'rate', b_did, sx_b_seed_hex, 'store', 'credit',
			'main')
		assert rm4.ftype == 3, 'rate attach: ${rm4.raw.bytestr()}'
		lets := '  [= \$claim [delegation id="d-rate" [tenant main] [from [principal "${sx_client_did}"]] [to [agent "${b_did}"]] [capabilities [read]] [bounds [rate 1 :per "1h"]]]]\n' +
			'  [= \$cred [\$vc:issue "${sx_client_did}" [\$bytes:from-hex "${sx_client_seed_hex}"] "${b_did}" \$claim]]\n'
		sxt_send(mut chr, sx_present_frame(tmp, 'rate', lets))
		pr := sxt_read_frame(mut chr, 5 * time.second) or { panic('no rate present reply') }
		assert pr.ftype == 3 && pr.raw.bytestr().contains('presented'), 'rate present: ${pr.raw.bytestr()}'
		ok := sxt_request(mut chr, 20, '[get hash="${hash}"]')
		assert ok.ftype == 3, 'first read under rate 1: ${ok.payload.bytestr()}'
		hit := sxt_request(mut chr, 21, '[get hash="${hash}"]')
		hp := hit.payload.bytestr()
		assert hit.ftype == 7 && hp.contains('CXER4713') && hp.contains('retry-after'), 'rate exhaustion must carry CXER4713 + retry-after on the wire: ${hp}'
		// the retry-after value is a positive integer (a rate bucket replenishes)
		ra := sx_attr(hp, 'retry-after')
		assert ra == '' || ra.int() >= 0, 'retry-after present: ${hp}' // attr-or-child form; presence asserted above
		chr.close()
	}

	// ── open-posture CXER5022: a floor daemon designates no revocations
	//    journal; a revocations-plane feed refuses with the peer-token code
	//    regardless of posture (the token gate is not the PEP). ──
	{
		_, xport2, tmp2, mut proc2 := sxt_boot_cfg(90, '') // NO grants = pure floor posture
		defer {
			proc2.signal_kill()
			proc2.wait()
			os.rmdir_all(tmp2) or {}
		}
		mut cho, om4 := sxt_attach(xport2, tmp2, 'openp', sx_client_did, sx_client_seed_hex,
			'store', 'credit peer store-feed', 'main')
		assert om4.ftype == 3, 'open-posture attach: ${om4.raw.bytestr()}'
		r := sxt_request(mut cho, 30, '[feed [planes "revocations"]]')
		assert r.ftype == 7 && r.payload.bytestr().contains('CXER5022'), 'open-posture revocations feed must refuse CXER5022: ${r.payload.bytestr()}'
		cho.close()
	}

	// ── feeds die with the connection: a tail subscription dropped WITHOUT a
	//    cancel is reaped when the connection closes — the daemon stays
	//    healthy and keeps serving new sessions (guards the connection-death
	//    leak/hang class; sx_conn_close_locked deletes feeds by conn_id). ──
	{
		mut chd, dm4 := sxt_attach(xport, tmp, 'die', sx_client_did, sx_client_seed_hex, 'store',
			'credit store-feed', 'main')
		assert dm4.ftype == 3, 'die attach: ${dm4.raw.bytestr()}'
		fs := sxt_request(mut chd, 40, '[feed [planes "docs"]]')
		assert fs.ftype == 3, 'die feed-sub: ${fs.payload.bytestr()}'
		// abrupt close — no cancel frame, no eos handshake
		chd.close()
		// the daemon is still accepting and serving: a fresh session subscribes
		// and receives the live insert its own put generates
		mut chn, nm4 := sxt_attach(xport, tmp, 'afterdie', sx_client_did, sx_client_seed_hex,
			'store', 'credit store-feed', 'main')
		assert nm4.ftype == 3, 'post-drop attach: ${nm4.raw.bytestr()}'
		fs2 := sxt_request(mut chn, 41, '[feed [planes "docs"]]')
		assert fs2.ftype == 3, 'post-drop feed-sub: ${fs2.payload.bytestr()}'
		nh := sx_attr(sxt_request(mut cha, 42, '[put [body::bytes 0x${sx_body_hex(tmp, 'afterdie',
			'[order id=43 total=4.3]')}]]').payload.bytestr(), 'hash')
		assert nh != ''
		ev := sxt_read_frame(mut chn, 5 * time.second) or {
			panic('daemon stopped serving after a connection was dropped (feed-teardown regression)')
		}
		assert ev.ftype == 2 && ev.payload.bytestr().contains('[insert plane="docs"'), 'post-drop live insert: ${ev.payload.bytestr()}'
		chn.close()
	}

	// ── R3.5 (audit F-21): a multi-SCALAR [planes] is a malformed shape and
	//    refuses loudly (CXER5019), never silently keeps the last scalar. The
	//    spec shape (§5.2) is ONE space-separated scalar: [planes "docs refs"].
	//    No-dual-accept: the alternative multi-child shape is not honored. ──
	{
		mut chp, pm4 := sxt_attach(xport, tmp, 'multiplanes', sx_client_did, sx_client_seed_hex,
			'store', 'credit store-feed', 'main')
		assert pm4.ftype == 3, 'multi-planes attach: ${pm4.raw.bytestr()}'
		// the single-scalar form is honored (the control)
		ok := sxt_request(mut chp, 50, '[feed [planes "docs refs"]]')
		assert ok.ftype == 3, 'single-scalar planes must be honored: ${ok.payload.bytestr()}'
		sxt_send(mut chp, sxt_frame_text(4, 50, '', false))
		sxt_read_frame(mut chp, 5 * time.second) or { panic('cancel eos') }
		// the multi-scalar form refuses loudly (never a silent keep-last)
		bad := sxt_request(mut chp, 51, '[feed [planes "docs" "refs"]]')
		assert bad.ftype == 7 && bad.payload.bytestr().contains('CXER5019'), 'multi-scalar [planes] must refuse CXER5019: ${bad.payload.bytestr()}'
		chp.close()
	}
}

// ── W5 §7/§7.1: the peer profile — the revocation-convergence pair ──────────
//
// TWO daemons. A (origin) designates a revocations journal, grants the test
// client the data classes and daemon B's identity the PEER class ONLY
// (narrower than read). B (consumer) peers to A (mutual XSP-AUTH, responder
// DID pinned) and folds arriving revocations into its revoked-set. The
// client's authority on B arrives ONLY by VC presentation, so a revocation
// journaled at A visibly narrows a LIVE session on B at its next PEP check
// (no reach-in — the session survives, its authority shrinks), and a NEW
// presentation of the revoked credential refuses at present time.
const sx_b2_seed_hex = 'f5e5767cf153319517630f226876b86c8160cc583bc013744c6bf255f5cc0ee5' // RFC 8032 TEST-1024

const sx_b2_pub_hex = '278117fc144c72340f67d0f2316e8386ceffbf2b2428c9c51fef7c597f1d426e'

fn test_store_xsp_peer() {
	base := sx_pick_port() + 60
	// derive the two client-side dids from their fixture pubkeys
	tmp0 := os.join_path(os.temp_dir(), 'cx-store-xsp-peer-pre-${os.getpid()}')
	os.rmdir_all(tmp0) or {}
	os.mkdir_all(tmp0) or { panic('mkdir ${tmp0}: ${err}') }
	defer {
		os.rmdir_all(tmp0) or {}
	}
	b_did := sx_run_cx('', sx_write(tmp0, 'bdid.cx', "[?lib 'cx-stdlib/did' :as did]\n[?lib 'cx-stdlib/bytes' :as bytes]\n[\$did:key-create [\$bytes:from-hex \"${sx_b_pub_hex}\"]]\n"))
	b2_did := sx_run_cx('', sx_write(tmp0, 'b2did.cx', "[?lib 'cx-stdlib/did' :as did]\n[?lib 'cx-stdlib/bytes' :as bytes]\n[\$did:key-create [\$bytes:from-hex \"${sx_b2_pub_hex}\"]]\n"))

	// daemon A — the origin: revocations journal designated, peer grant for
	// B's daemon identity, data grants for the client (who writes the
	// journal entries over the wire).
	// the client holds `peer` too — the un-negotiated-token lane below needs
	// a session the PEP permits so the transcript gate is what refuses.
	xsp_a := '\n    [grants [grant did="${sx_client_did}" caps="read write delete admin peer"] [grant did="${b2_did}" caps="peer"]]\n    [revocations journal="revocations"]'
	_, xporta, tmpa, mut proca := sxt_boot_xsp(base, sx_host_did, 'CX_STORE_XSP_SEED_A',
		sx_host_seed_hex, xsp_a, '', [])
	defer {
		proca.signal_kill()
		proca.wait()
		os.rmdir_all(tmpa) or {}
	}

	// daemon B — the consumer: peers to A (pinning A's did), enforcing
	// posture; the client's authority arrives only by presentation.
	xsp_b := '\n    [grants [grant did="${sx_client_did}" caps="read write delete admin peer"]]\n    [peers [peer url="xsp://127.0.0.1:${xporta}" did="${sx_host_did}" tenant="main"]]'
	_, xportb, tmpb, mut procb := sxt_boot_xsp(base + 2, b2_did, 'CX_STORE_XSP_SEED_B',
		sx_b2_seed_hex, xsp_b, '127.0.0.1:${xporta}', [])
	defer {
		procb.signal_kill()
		procb.wait()
		os.rmdir_all(tmpb) or {}
	}

	// ── A: the peer class is NARROWER than read; the plane gates are typed ──
	mut chp, pm4 := sxt_attach(xporta, tmpa, 'peerA', b2_did, sx_b2_seed_hex, 'store',
		'credit peer store-delta store-feed', 'main')
	assert pm4.ftype == 3, 'peer attach at A: ${pm4.raw.bytestr()}'
	defer {
		chp.close()
	}
	{
		rg := sxt_request(mut chp, 20, '[get hash="sha2-256:${'ab'.repeat(32)}"]')
		assert rg.ftype == 7 && rg.payload.bytestr().contains('CXER4700'), 'peer cap must not read: ${rg.payload.bytestr()}'
		rm := sxt_request(mut chp, 21, '[feed [planes "docs revocations"]]')
		assert rm.ftype == 7 && rm.payload.bytestr().contains('CXER5019'), 'mixed planes: ${rm.payload.bytestr()}'
	}
	// a session that never confirmed the peer token → CXER5022 (the client
	// HOLDS the peer capability — the transcript gate is what refuses)
	{
		mut chc, cm4 := sxt_attach(xporta, tmpa, 'nopeer', sx_client_did, sx_client_seed_hex,
			'store', 'credit store-feed', 'main')
		assert cm4.ftype == 3
		r := sxt_request(mut chc, 22, '[feed [planes "revocations"]]')
		assert r.ftype == 7 && r.payload.bytestr().contains('CXER5022'), 'un-negotiated peer token: ${r.payload.bytestr()}'
		chc.close()
	}
	// the peer subscription proper: durable seq positions + the reported
	// convergence bound
	{
		fs := sxt_request(mut chp, 23, '[feed [planes "revocations"]]')
		p := fs.payload.bytestr()
		assert fs.ftype == 3 && p.contains('[revocations tenant="revocations" head=0]')
			&& p.contains('[convergence feed-lag-ms=250 enforcement="next-pep-check"]'), 'revocations feed-sub: ${p}'
	}

	// ── B: the client's live session, authorized ONLY by the presentation ──
	vc_lets := '  [= \$claim [delegation id="d-peer-1" [tenant main] [from [principal "${sx_client_did}"]] [to [agent "${b_did}"]] [capabilities [read]]]]\n' +
		'  [= \$cred [\$vc:issue "${sx_client_did}" [\$bytes:from-hex "${sx_client_seed_hex}"] "${b_did}" \$claim {id: "urn:vc:revoke-me"}]]\n'
	m3_lets := vc_lets + '  [= \$vpt [\$cx:emit [vp \$cred]]]\n'
	mut chb, bm4 := sxt_attach_vp(xportb, tmpb, 'peercli', b_did, sx_b_seed_hex, 'store',
		'credit', '', m3_lets, '[vp \$vpt] ')
	assert bm4.ftype == 3, 'presented attach at B: ${bm4.raw.bytestr()}'
	defer {
		chb.close()
	}
	probe := '[get hash="sha2-256:${'ab'.repeat(32)}"]'
	{
		r := sxt_request(mut chb, 30, probe)
		assert r.ftype == 3 && sx_attr(r.payload.bytestr(), 'present') == 'false', 'pre-revocation read: ${r.payload.bytestr()}'
	}
	// B designates no revocations journal — it never offers the peer token,
	// so a would-be peer refuses typed (a daemon that cannot serve the
	// surface never pretends to)
	{
		mut chz, zm4 := sxt_attach(xportb, tmpb, 'noserve', sx_client_did, sx_client_seed_hex,
			'store', 'credit peer store-feed', 'main')
		assert zm4.ftype == 3
		r := sxt_request(mut chz, 31, '[feed [planes "revocations"]]')
		assert r.ftype == 7 && r.payload.bytestr().contains('CXER5022'), 'non-designating daemon: ${r.payload.bytestr()}'
		chz.close()
	}

	// ── the revocation, journaled at A (as data, over the wire) ──
	mut chw, wm4 := sxt_attach(xporta, tmpa, 'writer', sx_client_did, sx_client_seed_hex,
		'store', 'credit', 'main')
	assert wm4.ftype == 3
	{
		pay := '[revoke vc-id="urn:vc:revoke-me"]'
		rp := sxt_request(mut chw, 40, '[put [body::bytes 0x${sx_body_hex(tmp0, 'revpay', pay)}]]')
		p_hash := sx_attr(rp.payload.bytestr(), 'hash')
		assert p_hash != '', 'revocation payload put: ${rp.payload.bytestr()}'
		entry := '[entry seq=1 tenant="revocations" actor="did:op" authority="operator" ts="2026-08-07T12:00:00Z" prev-hash="genesis" payload="${p_hash}" hash="sha2-256:unverified"]'
		re := sxt_request(mut chw, 41, '[put [body::bytes 0x${sx_body_hex(tmp0, 'reventry',
			entry)}]]')
		e_hash := sx_attr(re.payload.bytestr(), 'hash')
		assert e_hash != '', 'revocation entry put: ${re.payload.bytestr()}'
		ra := sxt_request(mut chw, 42, '[aliases-set [a name="cx-journal/entry/revocations/1" hash="${e_hash}"]]')
		assert ra.ftype == 3, 'entry alias: ${ra.payload.bytestr()}'
	}
	chw.close()

	// the serving side tails it to the open peer subscription (§5.3 shape,
	// durable journal-seq position)
	{
		ev := sxt_read_frame(mut chp, 10 * time.second) or { panic('no revoke event at A') }
		pe := ev.payload.bytestr()
		assert ev.ftype == 2 && pe.contains('[revoke plane="revocations" pos=1 vc-id="urn:vc:revoke-me"]'), 'revoke event: ${pe}'
	}

	// ── R3.4 (audit F-26): the origin folds its OWN revocations journal ──
	// A fresh A-LOCAL session presenting the revoked credential is refused AT
	// the origin at present time (CXER5021 revoked) — the origin enforces its
	// own journal, not merely relays it to peers (the B-side refusal at the
	// tail of this test is the relay path). The refusal is asserted WITHIN
	// the §7.1 convergence contract ([convergence feed-lag-ms=250
	// enforcement="next-pep-check"]): the local fold rides the liveness
	// sweeper tick, so an attach racing the tick may still be admitted; the
	// contract promises enforcement within the bound, not instantly. (The
	// original instant-refusal assert pinned a stronger-than-contract
	// property and was nondeterministic by exactly the tick phase — it
	// admitted the session whenever the attach beat the 250ms fold tick.)
	{
		mut refused := false
		mut last := ''
		deadline := time.now().unix_milli() + 2000 // 8× the spec'd 250ms lag bound
		for time.now().unix_milli() < deadline {
			mut cho, om4 := sxt_attach_vp(xporta, tmpa, 'aorigin-revoked', b_did,
				sx_b_seed_hex, 'store', 'credit', '', m3_lets, '[vp \$vpt] ')
			last = om4.raw.bytestr()
			cho.close()
			if om4.ftype == 7 && last.contains('CXER5021') && last.contains('revoked') {
				refused = true
				break
			}
			time.sleep(100 * time.millisecond)
		}
		assert refused, 'origin must fold its OWN journal within the §7.1 convergence bound (present-time refusal at A): ${last}'
	}

	// ── R3.4: PEP-before-token-gate ordering ──
	// A session UNDER the enforcing posture that lacks the `peer` capability is
	// refused by the PEP (CXER4700), NOT the peer-token transcript gate
	// (CXER5022). Together with the cap-holding/token-lacking lane earlier in
	// this test (→ 5022), this pins the order: the PEP runs FIRST.
	{
		mut chn, nm4 := sxt_attach(xporta, tmpa, 'nopeercap', b_did, sx_b_seed_hex, 'store',
			'credit store-feed', 'main')
		assert nm4.ftype == 3, 'no-peer-cap attach: ${nm4.raw.bytestr()}'
		r := sxt_request(mut chn, 24, '[feed [planes "revocations"]]')
		p := r.payload.bytestr()
		assert r.ftype == 7 && p.contains('CXER4700') && !p.contains('CXER5022'), 'PEP must deny a no-peer-cap session BEFORE the token gate: ${p}'
		chn.close()
	}

	// ── R3.4: revocations-cursor resume ──
	// A fresh peer subscription resuming from pos=0 replays the durable pos=1
	// revoke — the peer worker's own resume path (store_xsp_peer.v folds from
	// the durable cursor), pinned directly on the wire.
	{
		mut chc, cm4 := sxt_attach(xporta, tmpa, 'revresume', b2_did, sx_b2_seed_hex, 'store',
			'credit peer store-feed', 'main')
		assert cm4.ftype == 3, 'revocations-resume attach: ${cm4.raw.bytestr()}'
		fs := sxt_request(mut chc, 25, '[feed [planes "revocations"] [from [s plane="revocations" pos=0]]]')
		assert fs.ftype == 3, 'revocations resume sub: ${fs.payload.bytestr()}'
		rev := sxt_read_frame(mut chc, 10 * time.second) or { panic('no replayed revoke on resume') }
		assert rev.payload.bytestr().contains('[revoke plane="revocations" pos=1 vc-id="urn:vc:revoke-me"]'), 'resume must replay the durable pos=1 revoke: ${rev.payload.bytestr()}'
		chc.close()
	}

	// ── R3.5 (audit F-21): a revocations cursor carries [s plane="revocations"
	//    pos=N] ONLY — a name= attr (meaningful only on the per-name refs/
	//    aliases planes) is malformed on the single-stream revocations plane and
	//    refuses loudly (CXER5019), never accepted-and-ignored. ──
	{
		mut chc, cm4 := sxt_attach(xporta, tmpa, 'revname', b2_did, sx_b2_seed_hex, 'store',
			'credit peer store-feed', 'main')
		assert cm4.ftype == 3, 'rev-name attach: ${cm4.raw.bytestr()}'
		r := sxt_request(mut chc, 26, '[feed [planes "revocations"] [from [s plane="revocations" name="head" pos=0]]]')
		p := r.payload.bytestr()
		assert r.ftype == 7 && p.contains('CXER5019'), 'name= on a revocations cursor must refuse CXER5019: ${p}'
		chc.close()
	}

	// ── convergence at B: the LIVE session narrows at its next PEP check ──
	mut denied := false
	mut last := ''
	for i in 0 .. 60 {
		r := sxt_request(mut chb, u64(50 + i), probe)
		last = r.payload.bytestr()
		if r.ftype == 7 {
			assert last.contains('CXER4700'), 'post-revocation deny: ${last}'
			denied = true
			break
		}
		time.sleep(250 * time.millisecond)
	}
	assert denied, 'revocation never converged at B (last: ${last})'

	// no reach-in: the session is ALIVE — only its authority narrowed
	{
		sxt_send(mut chb, sxt_frame_text(5, 77, 'still-here', false))
		pong := sxt_read_frame(mut chb, 5 * time.second) or { panic('no pong post-revocation') }
		assert pong.ftype == 6 && pong.payload.bytestr() == 'still-here', 'session must survive revocation: ${pong.ftype}'
	}

	// present-time refusal: a NEW presentation of the revoked credential
	{
		mut chn, nm4 := sxt_attach_vp(xportb, tmpb, 'revoked', b_did, sx_b_seed_hex, 'store',
			'credit', '', m3_lets, '[vp \$vpt] ')
		assert nm4.ftype == 7 && nm4.raw.bytestr().contains('CXER5021')
			&& nm4.raw.bytestr().contains('revoked'), 'revoked presentation: ${nm4.raw.bytestr()}'
		chn.close()
	}
}

// ── R3.4 (audit F-26): peer responder-DID PIN refusal ──────────────────────
// A consumer daemon that peers to an origin pins the origin's DID. If the
// daemon reached at that address presents a DIFFERENT identity, the peer
// worker REFUSES to fold its "revocations" (store_xsp_peer.v: responder !=
// peer.did) — an impostor origin can never inject a revocations surface. Two
// daemons: A (a real origin) and B pinning the WRONG did for A; B logs the
// pin refusal and never converges. Security-relevant, so pinned explicitly.
fn test_store_xsp_peer_wrong_did_pin() {
	base := sx_pick_port() + 80
	tmp0 := os.join_path(os.temp_dir(), 'cx-store-xsp-wrongpin-pre-${os.getpid()}')
	os.rmdir_all(tmp0) or {}
	os.mkdir_all(tmp0) or { panic('mkdir ${tmp0}: ${err}') }
	defer {
		os.rmdir_all(tmp0) or {}
	}
	b2_did := sx_run_cx('', sx_write(tmp0, 'b2did.cx', "[?lib 'cx-stdlib/did' :as did]\n[?lib 'cx-stdlib/bytes' :as bytes]\n[\$did:key-create [\$bytes:from-hex \"${sx_b2_pub_hex}\"]]\n"))

	// A — a real origin: designates a revocations journal, grants B's identity
	// the peer class.
	xsp_a := '\n    [grants [grant did="${b2_did}" caps="peer"]]\n    [revocations journal="revocations"]'
	_, xporta, tmpa, mut proca := sxt_boot_xsp(base, sx_host_did, 'CX_STORE_XSP_SEED_A',
		sx_host_seed_hex, xsp_a, '', [])
	defer {
		proca.signal_kill()
		proca.wait()
		os.rmdir_all(tmpa) or {}
	}

	// B — peers to A but pins the WRONG did (sx_client_did, not A's sx_host_did).
	// A presents sx_host_did; B's pin check fails; B refuses the fold.
	xsp_b := '\n    [peers [peer url="xsp://127.0.0.1:${xporta}" did="${sx_client_did}" tenant="main"]]'
	_, _, tmpb, mut procb := sxt_boot_xsp(base + 2, b2_did, 'CX_STORE_XSP_SEED_B',
		sx_b2_seed_hex, xsp_b, '127.0.0.1:${xporta}', [])
	defer {
		procb.signal_kill()
		procb.wait()
		os.rmdir_all(tmpb) or {}
	}

	// the peer worker retries on a timer; within a few seconds B's log carries
	// the pin refusal for the mis-identified origin.
	mut refused := false
	for _ in 0 .. 60 {
		log := os.read_file(os.join_path(tmpb, 'daemon.log')) or { '' }
		if log.contains('is not the pinned did') {
			refused = true
			break
		}
		time.sleep(250 * time.millisecond)
	}
	log := os.read_file(os.join_path(tmpb, 'daemon.log')) or { '' }
	assert refused, 'B must refuse a wrong-DID-pinned peer (no such log line):\n${log}'
	// the refusal names A's real identity vs the wrong pin — proving it is THIS
	// mismatch that fired, not some unrelated connect error
	assert log.contains('is not the pinned did "${sx_client_did}"'), 'refusal must name the wrong pinned did: ${log}'
	assert log.contains('"${sx_host_did}"'), 'refusal must report the origin\'s real identity: ${log}'
}

// ── R3.2 (audit F-23): the spec'd refusal rows that had zero wire tests ─────
// CXER5013 mount resolution at attach (xsp_store_profile.md registry): a
// tenant-less M3 against a daemon mounting MORE than one store is ambiguous
// and refuses — the sole-store shorthand must never guess; a [tenant] naming
// an unmounted store refuses. CXER5016 body-lane violations post-attach:
// [put] without the [body::bytes …] child; a body whose bytes are not
// decodable framed ast_bin. Both fault classes leave the session usable —
// the closing valid put proves the refusals are per-request, not
// connection-fatal. (CXER5015 internal-fault: no wire-constructible lane
// without mocks — every store-op failure reachable from a well-formed
// request surfaces as an err VALUE relayed verbatim, not the V-level error
// the 5015 arms catch; evidence in the remediation register R3.2 row.)
fn test_store_xsp_mount_and_body_faults() {
	_, xport, tmp, mut proc := sxt_boot_xsp(60, sx_host_did, 'CX_STORE_XSP_SEED',
		sx_host_seed_hex, '', '', ['main', 'aux'])
	defer {
		proc.signal_kill()
		proc.wait()
		os.rmdir_all(tmp) or {}
	}

	// tenant-less M3, two mounts → ambiguous → CXER5013 at attach
	{
		mut ch, m4 := sxt_attach(xport, tmp, 'ambig', sx_client_did, sx_client_seed_hex,
			'store', 'credit', '')
		assert m4.ftype == 7, 'ambiguous mount must refuse the attach, got type ${m4.ftype}'
		assert m4.raw.bytestr().contains('CXER5013'), 'ambiguous mount: ${m4.raw.bytestr()}'
		ch.close()
	}
	// [tenant] naming an unmounted store → CXER5013
	{
		mut ch, m4 := sxt_attach(xport, tmp, 'unknown', sx_client_did, sx_client_seed_hex,
			'store', 'credit', 'nope')
		assert m4.ftype == 7, 'unknown mount must refuse the attach, got type ${m4.ftype}'
		assert m4.raw.bytestr().contains('CXER5013'), 'unknown mount: ${m4.raw.bytestr()}'
		ch.close()
	}
	// positive control: NAMING a mount on the multi-store daemon attaches —
	// the refusals above are the resolution rule, not multi-mount breakage
	mut ch, m4 := sxt_attach(xport, tmp, 'aux', sx_client_did, sx_client_seed_hex,
		'store', 'credit', 'aux')
	assert m4.ftype == 3, 'named-mount attach failed: ${m4.raw.bytestr()}'
	defer {
		ch.close()
	}

	// CXER5016: put without a [body::bytes …] child
	{
		r := sxt_request(mut ch, 31, '[put]')
		assert r.ftype == 7 && r.payload.bytestr().contains('CXER5016'), 'bodyless put: ${r.payload.bytestr()}'
	}
	// CXER5016: bytes that are not decodable framed ast_bin
	{
		r := sxt_request(mut ch, 32, '[put [body::bytes 0xdeadbeef]]')
		assert r.ftype == 7 && r.payload.bytestr().contains('CXER5016'), 'bad ast_bin body: ${r.payload.bytestr()}'
	}
	// the session survives both refusals: a valid put still lands
	{
		body := sx_body_hex(tmp, 'ok-after-faults', '[note ok=true]')
		r := sxt_request(mut ch, 33, '[put [body::bytes 0x${body}]]')
		assert r.ftype == 3 && sx_attr(r.payload.bytestr(), 'stored') == 'true', 'put after faults: ${r.payload.bytestr()}'
	}
}

// ── S6 §4.3: the journal pushdown family is TRANSCRIPT-GATED ────────────────
// A session whose confirmed feature set lacks `store-journal` gets CXER5012
// on every family verb — the un-negotiated-vocabulary rule (§3), the same
// posture the feed's store-feed token carries.
fn test_store_xsp_journal_token_gate() {
	port, xport, tmp, mut proc := sxt_boot_cfg(70, '')
	defer {
		proc.signal_kill()
		proc.wait()
		os.rmdir_all(tmp) or {}
	}
	// offer 'credit' ONLY — store-journal deliberately absent from M1
	mut ch, m4 := sxt_attach(xport, tmp, 'jtok', sx_client_did, sx_client_seed_hex,
		'store', 'credit', 'main')
	assert m4.ftype == 3, 'attach: ${m4.raw.bytestr()}'
	defer {
		ch.close()
	}
	r := sxt_request(mut ch, 21, '[journal-read tenant="ledger" seq=1]')
	assert r.ftype == 7 && r.payload.bytestr().contains('CXER5012'), 'un-negotiated store-journal must refuse CXER5012: ${r.payload.bytestr()}'
	rf := sxt_request(mut ch, 22, '[journal-fold tenant="ledger" fn="sha2-256:${'ab'.repeat(32)}" claim="computes-as:sha2-256:${'cd'.repeat(32)}"]')
	assert rf.ftype == 7 && rf.payload.bytestr().contains('CXER5012'), 'compute verbs gate identically: ${rf.payload.bytestr()}'
}

// ── stream 9 (#681, W6): the WIRE sync composition — pull/reconcile/status
// against a cx-store+xsp:// peer. The peer lineage rides the new `log` op;
// aliases ride `aliases all`; doc text rides the remote read arm — ONE
// examination, two transports (PeerView). The daemon is the ORIGIN; the
// client's local mem store is the replica.
fn test_xsp_wire_pull_reconcile_status() {
	_, xport, tmp, mut proc := xc_boot()
	defer {
		xc_stop(mut proc, tmp)
	}
	url := 'cx-store+xsp://127.0.0.1:${xport}/main/'
	r := xc_run(tmp, xport, 'sync.cx', xc_lib +
		'[?let [= \$r [\$store:open "${url}"]]\n' +
		'[?let [= \$d1 [\$store:put-doc \$r [order [id 1]]]]\n' +
		'[?let [= \$x1 [\$store:set-alias \$r "head" \$d1]]\n' +
		'[?let [= \$l [\$store:open "mem://wire-replica"]]\n' +
		'[?let [= \$p1 [\$store:pull \$l \$r]]\n' +
		'[?let [= \$t1 [\$eq [\$store:get-alias \$l "head"] \$d1]]\n' +
		'[?let [= \$d2 [\$store:put-doc \$r [order [id 1] [line "srv"]]]]\n' +
		'[?let [= \$x2 [\$store:set-alias \$r "head" \$d2]]\n' +
		'[?let [= \$d4 [\$store:put-doc \$l [order [id 1] [note "tab"]]]]\n' +
		'[?let [= \$x4 [\$store:set-alias \$l "head" \$d4]]\n' +
		'[?let [= \$rep [\$store:pull-report \$l \$r]]\n' +
		'[?let [= \$st [\$store:status \$l {peer: \$r}]]\n' +
		'[result [ff \$p1/@ok] [target \$t1] [div \$rep/@ok] [peer [\$first \$st/peer]]]\n' +
		']]]]]]]]]]]]\n')
	assert r.exit_code == 0, 'wire sync exited ${r.exit_code}: ${r.output} | daemon: ${xc_daemon_log(tmp)}'
	assert r.output.contains('[ff true]'), 'the first wire pull fast-forwards: ${r.output}'
	assert r.output.contains('[target true]'), 'the replica ref lands on the origin tip: ${r.output}'
	assert r.output.contains('[div false]'), 'the diverged wire pull-report says ok=false: ${r.output}'
	assert r.output.contains('state=:diverged'), 'status {peer:} classifies the diverged ref over the wire: ${r.output}'
}
